/**
 * UI-030 — production score workspace (SCORE_READY+, GUI_UX_SPEC §6–§11).
 *
 * Verovio-based SVG rendering driven by a `ScoreDocumentPort` (fixture
 * adapter today; engine data slots in later). Responsibilities:
 *
 * - render MusicXML → SVG pages (inlined WASM, fully offline);
 * - note click → canonical `sn-*` selection → properties inspector;
 * - Concert ↔ F管ホルン switch preserving selection, transport position,
 *   loop, playback state, zoom and an equivalent viewport position
 *   (UI-005 verified semantics);
 * - playback hierarchy: caret → current-measure wash → active-note outline,
 *   all DOM-only marks — zero `renderToSVG` on the frame path;
 * - follow playback with manual-scroll suspension + explicit 追従を再開;
 * - review 要確認 markers (dotted cue, warning tint — never error red);
 * - zoom controls bound to the same methods the registry commands call.
 */
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { ja } from "../strings/ja";
import type { PitchViewSetting } from "../commands/types";
import type { ScoreDocumentPort } from "./document";
import { ScoreView } from "./ScoreView";
import {
  ACTIVE_CLASS,
  LOOP_CLASS,
  MEASURE_ACTIVE_CLASS,
  SELECTED_CLASS,
  buildElementIndex,
  clearCaret,
  drawCaret,
  markCanonical,
  markCanonicalSet,
  markMeasures,
  markReviewMarkers,
  measureElementOf,
  type ElementIndex,
} from "./domScore";
import { canonicalNoteIdFromMusicxml } from "./ids";
import {
  describeNote,
  notesByCanonical,
  notesByExportId,
  parseScoreDoc,
  type ParsedNote,
  type ScoreDoc,
} from "./scoreDoc";
import {
  getScoreRenderer,
  clampScoreZoom,
  SCORE_ZOOM_STEP_PCT,
  type RenderedPage,
  type ScoreRenderer,
  type ScoreViewMode,
} from "./verovio";
import {
  readScoreSessionView,
  writeScoreSessionView,
} from "../workspace/layout";
import {
  buildPlaybackTable,
  canonicalsInRange,
  segmentAt,
  type PlaybackTable,
} from "./playbackTable";
import { ScoreCursorClock, type ClockSnapshot, type TransportClock } from "./clock";
import { ScorePlaybackSynth, velocityByCanonicalId } from "./playbackSynth";
import { bendsByCanonicalId } from "./playbackSynth";
import { buildSwingWarp } from "./swingWarp";
import {
  allIssuesForCanonical,
  markedCanonicalIds,
  numEvidence,
  type ScoreReviewIssue,
} from "./review";
import { ReviewSession, type ReviewEdit } from "./reviewSession";
import { ReviewBar } from "./ReviewBar";
import {
  findCanonicalNote,
  formatFraction,
  scaleFraction,
  type RhythmEditInvoker,
  type RhythmEditOp,
} from "./rhythmEdits";
import {
  nextScoreNoteId,
  pitchBefore,
  restAtomAtOrdinal,
  restOrdinalOf,
} from "./restSpans";
import {
  buildNoteInspector,
  buildScoreInspector,
  keyLabelJa,
  type InspectorCopy,
  type InspectorModel,
} from "./inspector";
import type { ScoreWorkspaceController, ScoreWorkspaceState } from "./controller";
import { SegmentedControl } from "../components/primitives/SegmentedControl";
import { HsButton } from "../components/primitives/Button";

interface Selection {
  exportId: string;
  canonicalId: string | null;
}

interface Props {
  document: ScoreDocumentPort;
  pitch: PitchViewSetting;
  onInspectorChange(model: InspectorModel): void;
  onStateChange?(state: ScoreWorkspaceState): void;
  controllerRef?(controller: ScoreWorkspaceController | null): void;
  announce(message: string): void;
  /** [UI-020 handoff] live media-transport mirror. When present the score
   *  clock follows it — the media element is the one audio clock (UI-005
   *  "one clock" contract); when absent (no source loaded, dev/fixture
   *  playback) the score's own ScoreCursorClock is the transport. */
  transport?: {
    readonly isPlaying: boolean;
    readonly positionSec: number;
    readonly rate?: number;
  } | null;
  /** [UI-050] 元音源を再生 / jump-to-issue: drive the real media transport
   *  (seek + A-B loop on the issue's source range) when audio is loaded.
   *  When absent, the score clock plays the range so the passage is still
   *  indicated on the score (dev/fixture playback). */
  sourceControl?: {
    seekTo(sec: number): void;
    play(): void;
    setLoop(range: { start: number; end: number } | null): void;
  } | null;
  /** 設定→楽譜 初期表示 — seeds viewMode on mount (document key
   *  remounts per revision, so this is a per-score default). */
  initialViewMode?: ScoreViewMode;
  /** 設定→再生 再生位置を追従 — seeds the follow toggle. */
  followPlayback?: boolean;
  /** #115 (spec 13): engine score.edit invoker — absent for fixture/dev
   *  documents, where rhythm edits announce as unavailable instead of
   *  pretending to work. */
  onRhythmEdit?: RhythmEditInvoker;
  /** #148: re-run the job with the voices texture — offered on the
   *  merged-overlap review issue when auto detected a mix. */
  onRetranscribeVoices?(): void;
}

const EMPTY_SET: ReadonlySet<string> = new Set<string>();

function sameSet(a: ReadonlySet<string>, b: ReadonlySet<string>): boolean {
  if (a.size !== b.size) return false;
  for (const v of a) if (!b.has(v)) return false;
  return true;
}

/** Reason-code → copy deck. `ReviewReason` is forward-compatible
 *  (`string & {}`), so index through a plain record — unknown engine codes
 *  land on `other`. */
const REASON_DECK: Record<string, { readonly title: string; readonly detail: string }> =
  ja.reviewReasons;

/** Inspector copy — bound to ja.ts so Japanese text stays in one place. */
function inspectorCopy(): InspectorCopy {
  const j = ja.inspector;
  return {
    review: {
      // `?? other`: engine reason codes may be newer than this UI's copy
      // deck — the issue stays visible with generic copy (sidecar/review.ts
      // uses the same fallback policy).
      reasonTitle: (r) => (REASON_DECK[r] ?? ja.reviewReasons.other).title,
      reasonDetail: (issue: ScoreReviewIssue) => {
        // #85 voices texture: surface the split counts the engine put in
        // evidence — "kept N notes as a second voice, dropped M beyond
        // two voices" — instead of the generic overlap copy.
        if (issue.reason === "overlapping_candidates") {
          const second =
            numEvidence(issue, "extraVoiceNotes") ??
            numEvidence(issue, "secondVoiceNotes");
          const dropped = numEvidence(issue, "droppedBeyondVoices");
          if (second != null || dropped != null) {
            return ja.reviewEvidence.secondVoice(second ?? 0, dropped ?? 0);
          }
          const merged = numEvidence(issue, "polyphonicOverlaps");
          if (merged != null) {
            // #148: auto detected a mix — the detail names the
            // one-click voices retry the review bar now exposes.
            if (issue.evidence["suggestVoicesTexture"] === true) {
              return ja.reviewEvidence.mergedOverlapsSuggest(merged);
            }
            return ja.reviewEvidence.mergedOverlaps(merged);
          }
        }
        // #134 swing feel: report the offbeat census the detector saw
        // so the user can judge whether the piece is really a shuffle.
        if (issue.reason === "swing_feel") {
          const offbeats = numEvidence(issue, "offbeatOnsets");
          const swing = numEvidence(issue, "swingOnsets");
          if (offbeats != null && swing != null) {
            return ja.reviewEvidence.swingFeel(offbeats, swing);
          }
        }
        return (REASON_DECK[issue.reason] ?? ja.reviewReasons.other).detail;
      },
      severityLabel: (s) => ja.reviewSeverity[s] ?? ja.reviewSeverity.info,
      statusLabel: (s) => ja.reviewStatus[s] ?? ja.reviewStatus.open,
    },
    measure: (n) => ja.scoreView.measureNth(n),
    scoreSeconds: (sec) => j.scoreSeconds(sec),
    tieFragments: (n) => j.tieFragments(n),
    tempo: (bpm) => j.tempoLabel(bpm),
    measureCount: (n) => j.measureCountLabel(n),
    noteCount: (n) => j.noteCountLabel(n),
    openIssues: (n) => j.openIssuesLabel(n),
    key: (fifths) => j.keyLabel(keyLabelJa(fifths)),
  };
}

export function ScoreReadyWorkspace({
  document: scoreDoc,
  pitch,
  initialViewMode = "continuous",
  followPlayback = true,
  onInspectorChange,
  onStateChange,
  controllerRef,
  announce,
  transport,
  sourceControl = null,
  onRhythmEdit,
  onRetranscribeVoices,
}: Props) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<ScoreRenderer | null>(null);
  const indexRef = useRef<ElementIndex | null>(null);
  const clockRef = useRef<TransportClock | null>(null);
  const tableRef = useRef<PlaybackTable | null>(null);

  const [pages, setPages] = useState<RenderedPage[]>([]);
  /* §26: restore the previous session's score view (zoom + mode); the
   * settings "initial view" only applies when no session state exists. */
  const sessionViewRef = useRef(readScoreSessionView());
  const [viewMode, setViewMode] = useState<ScoreViewMode>(
    sessionViewRef.current.viewMode ?? initialViewMode,
  );
  const [currentPage, setCurrentPage] = useState(1);
  const [zoom, setZoom] = useState(
    sessionViewRef.current.zoomPct ?? 100,
  );
  const [selection, setSelection] = useState<Selection | null>(null);
  const [loading, setLoading] = useState(true);
  const [renderError, setRenderError] = useState(false);
  const [initError, setInitError] = useState<string | null>(null);
  const [followEnabled, setFollowEnabled] = useState(followPlayback);
  const [followSuspended, setFollowSuspended] = useState(false);
  const [reviewOpen, setReviewOpen] = useState(false);
  const [reviewIndex, setReviewIndex] = useState(0);
  const [clockSnap, setClockSnap] = useState<ClockSnapshot>({
    positionMs: 0,
    durationMs: 0,
    isPlaying: false,
    rate: 1,
    loop: null,
  });
  // FEAT-001: score audition engine. Lazily created when the user turns
  // the audition toggle on; synced with the score clock below.
  const synthRef = useRef<ScorePlaybackSynth | null>(null);
  const [auditionEnabled, setAuditionEnabled] = useState(false);
  const auditionRef = useRef(false);

  // Parsed presentations — identical canonical ids, different spelling.
  const docsRef = useRef<{
    concert: ScoreDoc;
    horn: ScoreDoc;
    concertByCanonical: Map<string, ParsedNote[]>;
    hornByCanonical: Map<string, ParsedNote[]>;
    concertByExport: Map<string, ParsedNote>;
    hornByExport: Map<string, ParsedNote>;
  } | null>(null);

  // Refs mirrored so the rAF pump / layout effect always see fresh values.
  const selectionRef = useRef<Selection | null>(null);
  const activeRef = useRef<ReadonlySet<string>>(EMPTY_SET);
  const loopCanonicalsRef = useRef<ReadonlySet<string>>(EMPTY_SET);
  const followRef = useRef(true);
  const suspendedRef = useRef(false);
  const zoomRef = useRef(sessionViewRef.current.zoomPct ?? 100);
  const viewModeRef = useRef<ScoreViewMode>(
    sessionViewRef.current.viewMode ?? initialViewMode,
  );
  const currentPageRef = useRef(1);
  const pitchRef = useRef(pitch);
  /** The presentation actually loaded into Verovio — compared against the
   *  `pitch` prop to detect a real view switch (the prop ref alone is
   *  updated every render and would mask the change). */
  const renderedPitchRef = useRef<PitchViewSetting | null>(null);
  const reviewIndexRef = useRef(0);
  const reviewOpenRef = useRef(false);
  const pendingScrollRef = useRef<{ ratio: number } | null>(null);

  /* ---- UI-050 review session ----
   * The document owns decisions + note edits (revision-bound); the session
   * owns the undo/redo command stack. `docVersion` bumps after every
   * mutation so memos/effects that read the document recompute. */
  const sessionRef = useRef<ReviewSession | null>(null);
  if (sessionRef.current === null) {
    sessionRef.current = new ReviewSession(scoreDoc);
  }
  const session = sessionRef.current;
  const [docVersion, setDocVersion] = useState(0);
  const bumpDoc = useCallback(() => setDocVersion((v) => v + 1), []);
  /* #115: engine rhythm edits are async — serialize them on a promise
   *  chain so a fast key repeat builds on the newest content instead of
   *  racing two score.edit calls against the same revision. */
  const rhythmQueueRef = useRef<Promise<void>>(Promise.resolve());

  const allIssues = useMemo(
    () => session.issues(),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [session, docVersion],
  );
  const pendingCount = useMemo(
    () => session.pendingCount(),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [session, docVersion],
  );
  const copy = useMemo(inspectorCopy, []);

  followRef.current = followEnabled;
  suspendedRef.current = followSuspended;
  zoomRef.current = zoom;
  viewModeRef.current = viewMode;
  currentPageRef.current = currentPage;
  pitchRef.current = pitch;
  reviewIndexRef.current = reviewIndex;
  reviewOpenRef.current = reviewOpen;

  /* ------------------------- DOM-only mark appliers ------------------------- */

  const applyActiveDom = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current;
    const container = scrollRef.current;
    if (!idx || !container) return;
    markCanonicalSet(idx, canonicals, ACTIVE_CLASS);
    const els: Element[] = [];
    for (const id of canonicals) els.push(...(idx.byCanonical.get(id) ?? []));
    markMeasures(container, els, MEASURE_ACTIVE_CLASS, true);
    // Playback caret: thin bar at the onset of the earliest active fragment.
    clearCaret(container);
    const first = els[0];
    if (first) {
      const measure = measureElementOf(first);
      if (measure && typeof (first as SVGGElement).getBBox === "function") {
        try {
          const box = (first as SVGGElement).getBBox();
          drawCaret(measure, box.x);
        } catch {
          /* no geometry — caret skipped, marks still applied */
        }
      }
    }
  }, []);

  const applyLoopDom = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current;
    if (!idx) return;
    markCanonicalSet(idx, canonicals, LOOP_CLASS);
  }, []);

  const scrollCanonicalIntoView = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current;
    if (!idx || canonicals.size === 0) return;
    const table = tableRef.current;
    let target: Element | null = null;
    if (table) {
      // Earliest onset leads the scroll target.
      let best = Number.POSITIVE_INFINITY;
      for (const id of canonicals) {
        const onset = table.onsetMsByCanonical.get(id) ?? Number.POSITIVE_INFINITY;
        if (onset < best) {
          best = onset;
          target = idx.byCanonical.get(id)?.[0] ?? null;
        }
      }
    }
    target ??= idx.byCanonical.get([...canonicals][0])?.[0] ?? null;
    target?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }, []);

  /* ------------------------------ rendering ------------------------------ */

  /** (Re)load + re-render the current presentation. Preserves the viewport
   *  ratio so the Concert↔F管 switch keeps an equivalent scroll position. */
  const renderScore = useCallback(
    (view: PitchViewSetting, opts: { keepScroll?: boolean } = {}) => {
      const r = rendererRef.current;
      const container = scrollRef.current;
      if (!r) return;
      if (opts.keepScroll && container) {
        const denom = Math.max(1, container.scrollHeight - container.clientHeight);
        pendingScrollRef.current = { ratio: container.scrollTop / denom };
      }
      try {
        r.setViewMode(viewModeRef.current);
        r.setZoom(zoomRef.current);
        const xml = scoreDoc.musicXml(view);
        const ok = r.load(xml);
        const parsed = ok ? parseScoreDoc(xml) : null;
        // UI-003 finding: loadData returns true for truncated-but-parseable
        // XML — verify content, not just the flag.
        if (!ok || !parsed || parsed.notes.length === 0) {
          throw new Error("score load produced no content");
        }
        renderedPitchRef.current = view;
        setPages(r.renderAllPages());
        setRenderError(false);
        setLoading(false);
      } catch {
        setPages([]);
        setRenderError(true);
        setLoading(false);
      }
    },
    [scoreDoc],
  );

  /** After every (re)render of the SVG: rebuild the element index and
   *  reapply selection/active/loop/caret marks — this is how all context
   *  survives zoom re-renders and Concert↔F管 switches (UI-005 pattern). */
  useLayoutEffect(() => {
    const container = scrollRef.current;
    if (!container || pages.length === 0) return;
    indexRef.current = buildElementIndex(container);
    markReviewMarkers(
      container,
      indexRef.current,
      markedCanonicalIds(scoreDoc.reviewIssues()),
    );
    const sel = selectionRef.current;
    if (sel?.canonicalId) {
      markCanonical(indexRef.current, sel.canonicalId, SELECTED_CLASS);
    } else if (sel) {
      indexRef.current.byExportId.get(sel.exportId)?.classList.add(SELECTED_CLASS);
    }
    markCanonicalSet(indexRef.current, activeRef.current, ACTIVE_CLASS);
    markCanonicalSet(indexRef.current, loopCanonicalsRef.current, LOOP_CLASS);
    const actEls: Element[] = [];
    for (const id of activeRef.current) {
      actEls.push(...(indexRef.current.byCanonical.get(id) ?? []));
    }
    markMeasures(container, actEls, MEASURE_ACTIVE_CLASS, true);

    // Page mode: clamp the current page when the document repaginates
    // (zoom / view switch can change the page count).
    if (viewModeRef.current === "page" && currentPageRef.current > pages.length) {
      setCurrentPage(pages.length);
    }

    // Equivalent viewport position (issue §Context preservation): a
    // selection re-reveals its note; otherwise the scroll ratio carries over.
    const pending = pendingScrollRef.current;
    pendingScrollRef.current = null;
    if (sel?.canonicalId) {
      indexRef.current.byCanonical
        .get(sel.canonicalId)?.[0]
        ?.scrollIntoView({ block: "nearest", inline: "nearest" });
    } else if (pending && viewModeRef.current === "continuous") {
      const denom = Math.max(1, container.scrollHeight - container.clientHeight);
      container.scrollTop = pending.ratio * denom;
    }
    // viewMode/currentPage swap the rendered DOM in page mode — the element
    // index must be rebuilt or marks would land on detached nodes.
    // docVersion re-applies review marks after a decision resolves an issue
    // without re-rendering the SVG.
  }, [pages, scoreDoc, viewMode, currentPage, docVersion]);

  /* ------------------------------ init ----------------------------------- */

  // Init per mounted document (App remounts on revision change via `key`).
  // StrictMode-safe: no "did init" latch — the cleanup's `cancelled` flag is
  // the guard, so the replayed effect initializes cleanly.
  useEffect(() => {
    let cancelled = false;
    getScoreRenderer()
      .then((r) => {
        if (cancelled) return;
        rendererRef.current = r;
        // Parse both presentations once — inspector reads both regardless of
        // the current view (written/concert rows, §22).
        const concert = parseScoreDoc(scoreDoc.musicXml("concert"));
        const horn = parseScoreDoc(scoreDoc.musicXml("hornF"));
        docsRef.current = {
          concert,
          horn,
          concertByCanonical: notesByCanonical(concert),
          hornByCanonical: notesByCanonical(horn),
          concertByExport: notesByExportId(concert),
          hornByExport: notesByExportId(horn),
        };
        renderScore(pitchRef.current);
        // Canonical timing is identical across presentations (same
        // durations + tempo), so the playback table is built once.
        // #156: swing-marked scores get a written->sounding warp so
        // audition + follow land on the swung positions (Verovio's
        // timemap ignores <swing>).
        tableRef.current = buildPlaybackTable(
          r.timemap(),
          buildSwingWarp(scoreDoc.canonicalDocument?.() ?? null) ??
            undefined,
        );
        const clock = new ScoreCursorClock(tableRef.current.durationMs);
        clockRef.current = clock;
        clock.subscribe(setClockSnap);
        // FEAT-001: audition engine follows the score clock. It consumes
        // the same PlaybackTable + the CONCERT ParsedNote map (sounding
        // pitch — the written horn view never drives pitch, because the
        // audition exists to check the transcribed *sounding* result).
        const synth = new ScorePlaybackSynth();
        synthRef.current = synth;
        synth.load(
          tableRef.current,
          notesByCanonical(concert),
          velocityByCanonicalId(scoreDoc.canonicalDocument?.() ?? null),
          bendsByCanonicalId(scoreDoc.canonicalDocument?.() ?? null),
        );
        clock.subscribe((s) => {
          synth.setLoop(s.loop ? { startMs: s.loop.startMs, endMs: s.loop.endMs } : null);
          synth.sync(s.positionMs, s.isPlaying, s.rate);
        });
      })
      .catch((e: unknown) =>
        setInitError(e instanceof Error ? e.message : String(e)),
      );
    return () => {
      cancelled = true;
      clockRef.current?.dispose();
      clockRef.current = null;
      synthRef.current?.dispose();
      synthRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ---- media transport handoff (UI-020 → UI-030) ----
   * The media element is the authoritative audio clock once a source is
   * loaded: the score clock follows its play state and snaps to its
   * position on real drift (seek, waveform click, rate change). Without a
   * live transport the score clock stays self-driven (fixture playback). */
  const extPlaying = transport?.isPlaying;
  const extSec = transport?.positionSec;
  const extRate = transport?.rate;
  useEffect(() => {
    if (extPlaying == null || extSec == null) return;
    const clock = clockRef.current;
    if (!clock) return;
    if (extPlaying !== clock.isPlaying()) {
      if (extPlaying) clock.play();
      else clock.pause();
    }
    if (extRate != null && extRate !== clock.rate()) clock.setRate(extRate);
    // Snap on real divergence only — the media timeupdate cadence is
    // coarser than the rAF clock, so small deltas are left alone.
    if (Math.abs(clock.positionMs() - extSec * 1000) > 200) {
      clock.seek(extSec * 1000);
    }
  }, [extPlaying, extSec, extRate]);

  /* --------------------- per-frame sync pump (DOM-only) -------------------- */
  /* Reads the transport clock each frame; DOM marks apply only when the     */
  /* active canonical set changes — React state never updates at frame rate. */

  useEffect(() => {
    let raf = 0;
    const tick = () => {
      const clock = clockRef.current;
      const table = tableRef.current;
      const idx = indexRef.current;
      if (clock && table && idx) {
        const seg = segmentAt(table, clock.positionMs());
        const set = seg?.canonicalIds ?? EMPTY_SET;
        if (!sameSet(set, activeRef.current)) {
          activeRef.current = set;
          applyActiveDom(set);
          if (
            followRef.current &&
            !suspendedRef.current &&
            clock.isPlaying() &&
            set.size > 0
          ) {
            if (viewModeRef.current === "page") {
              const r = rendererRef.current;
              const exportId = table.exportIdsByCanonical.get([...set][0])?.[0];
              const page = exportId && r ? r.pageWithElement(exportId) : 0;
              if (page > 0 && page !== currentPageRef.current) {
                setCurrentPage(page);
              }
            } else {
              scrollCanonicalIntoView(set);
            }
          }
        }
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [applyActiveDom, scrollCanonicalIntoView]);

  // Loop range → score passage marks (UI-005: half-open overlap semantics).
  useEffect(() => {
    const table = tableRef.current;
    if (!table) return;
    const loop = clockSnap.loop;
    const set = loop ? canonicalsInRange(table, loop.startMs, loop.endMs) : new Set<string>();
    if (!sameSet(set, loopCanonicalsRef.current)) {
      loopCanonicalsRef.current = set;
      applyLoopDom(set);
    }
  }, [clockSnap.loop, applyLoopDom]);

  /* --------------------------- selection -------------------------------- */

  const reportInspector = useCallback(() => {
    const docs = docsRef.current;
    const sel = selectionRef.current;
    if (!docs) return;
    if (!sel) {
      onInspectorChange(
        buildScoreInspector(scoreDoc.meta, pendingCount, copy),
      );
      return;
    }
    const canonical = sel.canonicalId;
    const concertFrags = canonical
      ? (docs.concertByCanonical.get(canonical) ?? [])
      : [docs.concertByExport.get(sel.exportId) ?? docs.hornByExport.get(sel.exportId)]
          .filter((n): n is ParsedNote => n != null);
    const hornFrags = canonical
      ? (docs.hornByCanonical.get(canonical) ?? [])
      : concertFrags;
    const onsetMs = canonical
      ? (tableRef.current?.onsetMsByCanonical.get(canonical) ?? null)
      : null;
    onInspectorChange(
      buildNoteInspector({
        canonicalId: canonical,
        concert: concertFrags,
        written: hornFrags,
        onsetMs,
        // UI-050: all issues for the note (open AND decided) — the status
        // label column keeps resolved rows readable in the inspector.
        issues: canonical
          ? allIssuesForCanonical(scoreDoc.reviewIssues(), canonical)
          : [],
        copy,
      }),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scoreDoc, pendingCount, docVersion, copy, onInspectorChange]);

  /** Select by export id; canonical notes also seek the transport to the
   *  note onset (§10: 原音位置と対応). */
  const selectExportId = useCallback(
    (exportId: string, opts: { seek?: boolean; scroll?: boolean } = {}) => {
      const canonicalId = canonicalNoteIdFromMusicxml(exportId);
      const sel: Selection = { exportId, canonicalId };
      selectionRef.current = sel;
      setSelection(sel);
      const idx = indexRef.current;
      if (idx) {
        markCanonical(idx, canonicalId, SELECTED_CLASS);
        if (!canonicalId) {
          idx.byExportId.get(exportId)?.classList.add(SELECTED_CLASS);
        }
      }
      reportInspector();
      const parsed =
        (canonicalId
          ? docsRef.current?.concertByCanonical.get(canonicalId)?.[0]
          : docsRef.current?.concertByExport.get(exportId)) ??
        docsRef.current?.hornByExport.get(exportId);
      if (parsed) announce(describeNote(parsed));
      const onsetMs = canonicalId
        ? tableRef.current?.onsetMsByCanonical.get(canonicalId)
        : undefined;
      if (opts.seek !== false && onsetMs != null) {
        clockRef.current?.seek(onsetMs);
      }
      if (opts.scroll && idx) {
        idx.byCanonical.get(canonicalId ?? "")?.[0]?.scrollIntoView({
          block: "nearest",
          inline: "nearest",
        });
      }
    },
    [announce, reportInspector],
  );

  const clearSelection = useCallback(() => {
    selectionRef.current = null;
    setSelection(null);
    const idx = indexRef.current;
    if (idx) markCanonical(idx, null, SELECTED_CLASS);
    reportInspector();
    announce(ja.scoreView.deselected);
  }, [announce, reportInspector]);

  /* --------------------------- follow mode ------------------------------- */

  const suspendFollow = useCallback(() => {
    // Only meaningful while playback is actually following (§11); a paused
    // score can scroll freely without nagging the user.
    if (!followRef.current || suspendedRef.current || !clockRef.current?.isPlaying()) {
      return;
    }
    suspendedRef.current = true;
    setFollowSuspended(true);
  }, []);

  const resumeFollow = useCallback(() => {
    suspendedRef.current = false;
    setFollowSuspended(false);
    setFollowEnabled(true);
    followRef.current = true;
    scrollCanonicalIntoView(activeRef.current);
  }, [scrollCanonicalIntoView]);

  /* ---------------------------- view switch ------------------------------ */
  /* Concert↔F管: re-render the other presentation. Canonical ids, the       */
  /* transport clock, selection, loop and zoom are all view-independent —    */
  /* marks reapply in the layout effect above; playback never pauses.        */

  useEffect(() => {
    if (!rendererRef.current || pitch === renderedPitchRef.current) return;
    renderScore(pitch, { keepScroll: true });
  }, [pitch, renderScore]);

  const changeZoom = useCallback(
    (pct: number) => {
      const next = clampScoreZoom(pct);
      if (next === zoomRef.current) return;
      zoomRef.current = next;
      setZoom(next);
      writeScoreSessionView({ zoomPct: next });
      renderScore(pitchRef.current, { keepScroll: true });
    },
    [renderScore],
  );

  const zoomFit = useCallback(() => {
    const container = scrollRef.current;
    const svg = container?.querySelector(".hs-score-page > svg");
    if (!container || !svg) return;
    const width = svg.getBoundingClientRect().width;
    if (width <= 0) return;
    const target = Math.floor((container.clientWidth - 32) * (zoomRef.current / width));
    changeZoom(target);
  }, [changeZoom]);

  const changeViewMode = useCallback(
    (mode: ScoreViewMode) => {
      if (mode === viewModeRef.current) return;
      viewModeRef.current = mode;
      setViewMode(mode);
      writeScoreSessionView({ viewMode: mode });
      renderScore(pitchRef.current, { keepScroll: true });
    },
    [renderScore],
  );

  /* ------------------------------ review --------------------------------- */
  /* UI-050: the cursor walks the FULL issue list (resolved issues stay
   *  reachable so their status/decision can be revisited and undone);
   *  markers + pendingCount come from the still-open subset. */

  const issueAtCursor = useCallback(
    () => allIssues[reviewIndexRef.current] ?? null,
    [allIssues],
  );

  const gotoIssue = useCallback(
    (index: number) => {
      const issues = allIssues;
      if (issues.length === 0) return;
      const i = ((index % issues.length) + issues.length) % issues.length;
      reviewIndexRef.current = i;
      setReviewIndex(i);
      const issue = issues[i];
      const table = tableRef.current;
      const canonicalId = issue.canonicalNoteIds[0];
      const exportId = canonicalId
        ? table?.exportIdsByCanonical.get(canonicalId)?.[0]
        : undefined;
      if (exportId) {
        // Page mode: jump to the containing page first — the layout effect
        // re-applies the selection mark on the freshly shown page.
        if (viewModeRef.current === "page") {
          const r = rendererRef.current;
          const page = r ? r.pageWithElement(exportId) : 0;
          if (page > 0 && page !== currentPageRef.current) {
            setCurrentPage(page);
          }
        }
        selectExportId(exportId, {
          scroll: viewModeRef.current !== "page",
        });
        // Select ALL associated canonical notes visually — an issue may
        // span several (e.g. a tie chain); the first stays the canonical
        // selection for the inspector.
        const idx = indexRef.current;
        if (idx && issue.canonicalNoteIds.length > 1) {
          markCanonicalSet(idx, new Set(issue.canonicalNoteIds), SELECTED_CLASS);
        }
      }
      // Position the source cursor at the issue's range start so
      // 元音源を再生 is immediate (acceptance: replay without extra steps).
      const startSec = issue.timeRange?.startSec;
      if (startSec != null) sourceControl?.seekTo(startSec);
      announce(ja.review.position(i + 1, issues.length));
    },
    [allIssues, selectExportId, sourceControl, announce],
  );

  const openReview = useCallback(() => {
    if (allIssues.length === 0) {
      announce(ja.review.feedback.noIssues);
      return;
    }
    reviewOpenRef.current = true;
    setReviewOpen(true);
    // Enter on the first still-open issue; when everything is resolved the
    // bar shows the all-done state at the top of the list.
    const firstOpen = allIssues.findIndex((i) => i.status === "open");
    gotoIssue(firstOpen >= 0 ? firstOpen : 0);
  }, [allIssues, gotoIssue, announce]);

  const exitReview = useCallback(() => {
    reviewOpenRef.current = false;
    setReviewOpen(false);
    announce(ja.review.feedback.exited);
  }, [announce]);

  /** Re-parse presentations + re-render after a note edit (pitch/delete):
   *  inspector labels and the playback table both derive from the XML. */
  const reloadEditedScore = useCallback(() => {
    const concert = parseScoreDoc(scoreDoc.musicXml("concert"));
    const horn = parseScoreDoc(scoreDoc.musicXml("hornF"));
    docsRef.current = {
      concert,
      horn,
      concertByCanonical: notesByCanonical(concert),
      hornByCanonical: notesByCanonical(horn),
      concertByExport: notesByExportId(concert),
      hornByExport: notesByExportId(horn),
    };
    renderScore(pitchRef.current, { keepScroll: true });
    const r = rendererRef.current;
    if (r) {
      tableRef.current = buildPlaybackTable(
        r.timemap(),
        buildSwingWarp(scoreDoc.canonicalDocument?.() ?? null) ??
          undefined,
      );
      // #170: the edit changed the notated content — refresh the audition
      // note list and the score clock's total span so the heard score and
      // the transport length match the edited score (previously both kept
      // the pre-edit notes/duration).
      synthRef.current?.load(
        tableRef.current,
        notesByCanonical(concert),
        velocityByCanonicalId(scoreDoc.canonicalDocument?.() ?? null),
        bendsByCanonicalId(scoreDoc.canonicalDocument?.() ?? null),
      );
      clockRef.current?.setDuration(tableRef.current.durationMs);
    }
  }, [scoreDoc, renderScore]);

  /** Apply a session action: bump the document version so derived views
   *  (markers, inspector, counts) refresh; reload the score when the edit
   *  changed notation. Returns false on a no-op (caller announces). */
  const runReviewEdit = useCallback(
    (
      edit: ReviewEdit | null,
      feedback: string,
      opts: { reload?: boolean } = {},
    ): boolean => {
      if (!edit) return false;
      bumpDoc();
      if (opts.reload ?? (edit.noteChanges.length > 0 || edit.docSwap != null)) {
        reloadEditedScore();
      }
      reportInspector();
      announce(feedback);
      return true;
    },
    [bumpDoc, reloadEditedScore, reportInspector, announce],
  );

  const reviewAccept = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue) return;
    if (!runReviewEdit(session.decide(issue.id, "accepted"), ja.review.feedback.accepted)) {
      announce(ja.review.feedback.already(ja.reviewStatus.accepted));
    }
  }, [issueAtCursor, session, runReviewEdit, announce]);

  const reviewDismiss = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue) return;
    if (!runReviewEdit(session.decide(issue.id, "dismissed"), ja.review.feedback.dismissed)) {
      announce(ja.review.feedback.already(ja.reviewStatus.dismissed));
    }
  }, [issueAtCursor, session, runReviewEdit, announce]);

  const reviewPitch = useCallback(
    (delta: number) => {
      const issue = issueAtCursor();
      if (!issue) return;
      if (!runReviewEdit(session.adjustPitch(issue.id, delta), ja.review.feedback.pitchFixed, { reload: true })) {
        announce(ja.review.feedback.noIssues);
      }
    },
    [issueAtCursor, session, runReviewEdit, announce],
  );

  const reviewDeleteOrRestore = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue || issue.canonicalNoteIds.length === 0) return;
    const deleted = session.isDeleted(issue.canonicalNoteIds[0]);
    runReviewEdit(
      session.setNoteDeleted(issue.id, !deleted),
      deleted ? ja.review.feedback.noteRestored : ja.review.feedback.noteDeleted,
      { reload: true },
    );
  }, [issueAtCursor, session, runReviewEdit]);

  /* #114 (spec 10/13): score-workspace note navigation + direct edits.
   *  Arrow keys walk canonical notes in document order; Alt+arrows /
   *  Delete / E edit the selection through the shared undo stack. */
  const selectAdjacentNote = useCallback(
    (direction: 1 | -1) => {
      const docs = docsRef.current;
      if (!docs) return;
      const canonicals = docs.concert.notes
        .map((n) => n.canonicalId)
        .filter((id): id is string => id != null);
      if (canonicals.length === 0) return;
      const cur = selectionRef.current?.canonicalId ?? null;
      let next: string;
      if (cur == null) {
        next = direction === 1 ? canonicals[0] : canonicals[canonicals.length - 1];
      } else {
        const i = canonicals.indexOf(cur);
        const j = i < 0 ? (direction === 1 ? 0 : canonicals.length - 1) : i + direction;
        if (j < 0 || j >= canonicals.length) return; // stay at the edges
        next = canonicals[j];
      }
      const exportId = docs.concertByCanonical.get(next)?.[0]?.exportId;
      if (exportId) selectExportId(exportId, { scroll: true });
    },
    [selectExportId],
  );

  const editSelectedPitch = useCallback(
    (delta: number) => {
      const canonicalId = selectionRef.current?.canonicalId;
      if (!canonicalId) return;
      if (
        !runReviewEdit(
          session.editNote(canonicalId, {
            pitchDelta: session.noteEditOf(canonicalId).pitchDelta + delta,
          }),
          ja.review.feedback.pitchFixed,
          { reload: true },
        )
      ) {
        announce(ja.review.feedback.noIssues);
      }
    },
    [session, runReviewEdit, announce],
  );

  const toggleSelectedDeleted = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    const deleted = session.isDeleted(canonicalId);
    runReviewEdit(
      session.editNote(canonicalId, { deleted: !deleted }),
      deleted ? ja.review.feedback.noteRestored : ja.review.feedback.noteDeleted,
      { reload: true },
    );
  }, [session, runReviewEdit]);

  const toggleSelectedEnharmonic = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    const cur = session.noteEditOf(canonicalId).enharmonic ?? false;
    if (
      !runReviewEdit(
        session.editNote(canonicalId, { enharmonic: !cur }),
        ja.review.feedback.respelled,
        { reload: true },
      )
    ) {
      announce(ja.review.feedback.noIssues);
    }
  }, [session, runReviewEdit, announce]);

  /* #115 (spec 13): engine rhythm edits — duration ladder, onset grid
   *  shift, tie toggle. The engine re-realizes the affected measures
   *  and returns fresh MusicXML + a new revision; the document swaps
   *  its content in place so selection and this undo stack survive
   *  (a remount would lose both). Undo restores the previous snapshot
   *  through the shared ReviewSession stack. */
  const applyRhythmEdit = useCallback(
    (
      buildOp: (canonical: unknown) => RhythmEditOp | null,
      feedback: string,
      after?: () => void,
    ) => {
      if (!onRhythmEdit || !scoreDoc.replaceContent) {
        announce(ja.commandFeedback.rhythmEditUnavailable);
        return;
      }
      // Serialize engine edits: each call must see the newest content.
      rhythmQueueRef.current = rhythmQueueRef.current.then(async () => {
        const canonical = scoreDoc.canonicalDocument?.();
        const prev = scoreDoc.contentSnapshot?.();
        if (canonical == null || !prev) {
          announce(ja.commandFeedback.rhythmEditUnavailable);
          return;
        }
        const op = buildOp(canonical);
        if (!op) {
          announce(ja.commandFeedback.rhythmEditFailed);
          return;
        }
        try {
          const result = await onRhythmEdit(canonical, op);
          const next = {
            concertXml: result.musicXmlConcert,
            hornXml: result.musicXmlHornF,
            revisionId: result.scoreRevision,
            canonicalDocument: result.scoreDocument,
          };
          scoreDoc.replaceContent?.(next);
          session.commitDocSwap(prev, next);
          bumpDoc();
          reloadEditedScore();
          reportInspector();
          announce(feedback);
          after?.();
        } catch {
          announce(ja.commandFeedback.rhythmEditFailed);
        }
      });
    },
    [
      scoreDoc,
      onRhythmEdit,
      session,
      bumpDoc,
      reloadEditedScore,
      reportInspector,
      announce,
    ],
  );

  /** 音価を2倍/半分 — the duration ladder walks ×2/÷2 on the canonical
   *  note's written length (a quarter → half → whole ...). */
  const noteDurationScale = useCallback(
    (power: number) => {
      const canonicalId = selectionRef.current?.canonicalId;
      if (!canonicalId) return;
      applyRhythmEdit(
        (canonical) => {
          const note = findCanonicalNote(canonical, canonicalId);
          if (!note) return null;
          const next = scaleFraction(note.durationBeats, power);
          if (!next) return null;
          return {
            kind: "setDuration",
            noteId: canonicalId,
            durationBeats: formatFraction(next),
          };
        },
        ja.commandFeedback.rhythmEdited,
      );
    },
    [applyRhythmEdit],
  );

  /** 発音位置を左/右へ — shift the onset by whole minimum-grid steps. */
  const shiftSelectedOnset = useCallback(
    (steps: number) => {
      const canonicalId = selectionRef.current?.canonicalId;
      if (!canonicalId) return;
      applyRhythmEdit(
        () => ({ kind: "shiftOnset", noteId: canonicalId, steps }),
        ja.commandFeedback.rhythmEdited,
      );
    },
    [applyRhythmEdit],
  );

  /** 次の音符とタイで結ぶ/解く — the engine validates the contiguous
   *  same-pitch partner and reports a rejection honestly. */
  const toggleSelectedTie = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    applyRhythmEdit(
      () => ({ kind: "toggleTie", noteId: canonicalId }),
      ja.commandFeedback.tieToggled,
    );
  }, [applyRhythmEdit]);

  /* spec 14 BPM edit - the properties panel's tempo field commits here.
   * setTempo is note-independent (it rewrites the tempo map's head
   * segment), so the op carries no noteId; the engine still returns a
   * fresh revision + rebuilt XML, which keeps undo on the same stack. */
  const setTempo = useCallback(
    (bpm: number) => {
      applyRhythmEdit(
        () => ({ kind: "setTempo", noteId: "", bpm }),
        ja.commandFeedback.tempoChanged,
      );
    },
    [applyRhythmEdit],
  );

  /* #129 (spec 14): meter edit — the engine re-tiles every part under
   * the new signature (positions rescale when the beat unit changes);
   * same serialized queue + undo stack as the other rhythm edits. */
  const setMeter = useCallback(
    (beatsPerMeasure: number, beatUnit: number) => {
      applyRhythmEdit(
        () => ({
          kind: "setMeter",
          noteId: "",
          beatsPerMeasure,
          beatUnit,
        }),
        ja.commandFeedback.meterChanged,
      );
    },
    [applyRhythmEdit],
  );

  /* #145 (spec 14): key edit — replaces the head signature and
   * collapses detected key changes to the new single key; same
   * serialized queue + undo stack as the other rhythm edits. */
  const setKey = useCallback(
    (fifths: number) => {
      applyRhythmEdit(
        () => ({ kind: "setKey", noteId: "", fifths }),
        ja.commandFeedback.keyChanged,
      );
    },
    [applyRhythmEdit],
  );

  /* #130 (spec 14): re-quantize the whole score under changed
   * quantization settings — the engine replays the canonical notes
   * through the DP with the merged profile. */
  const requantize = useCallback(
    (settings: Record<string, unknown>) => {
      applyRhythmEdit(
        () => ({ kind: "requantize", noteId: "", settings }),
        ja.commandFeedback.requantized,
      );
    },
    [applyRhythmEdit],
  );

  /* #131 (spec 13 post-MVP): split at the grid-snapped midpoint; merge
   * with the contiguous next same-pitch note — the engine validates
   * both (too short to split, different pitch, non-contiguous) and
   * reports a rejection honestly. */
  const splitSelectedNote = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    applyRhythmEdit(
      () => ({ kind: "splitNote", noteId: canonicalId }),
      ja.commandFeedback.noteSplit,
    );
  }, [applyRhythmEdit]);

  const mergeSelectedNotes = useCallback(() => {
    const canonicalId = selectionRef.current?.canonicalId;
    if (!canonicalId) return;
    applyRhythmEdit(
      () => ({ kind: "mergeNotes", noteId: canonicalId }),
      ja.commandFeedback.notesMerged,
    );
  }, [applyRhythmEdit]);

  /* #163: the selected rest becomes a note at its own atom position —
   * default pitch = the nearest preceding note's, default duration =
   * the rest atom's span (the engine re-tiles leftovers as rests).
   * Afterwards the fresh note is selected so pitch/duration edits are
   * one keystroke away. */
  const convertSelectedRest = useCallback(() => {
    const sel = selectionRef.current;
    const ordinal = sel ? restOrdinalOf(sel.exportId) : null;
    if (sel == null || ordinal == null) return;
    // The engine assigns the next free sn-* id — capture it from the
    // PRE-edit canonical inside buildOp (after the swap the counter
    // has already moved past the new note).
    let newNoteExportId: string | null = null;
    applyRhythmEdit(
      (canonical) => {
        const target = restAtomAtOrdinal(canonical, ordinal);
        if (!target) return null;
        newNoteExportId = nextScoreNoteId(canonical).replace(/^sn-/, "hs-sn-");
        return {
          kind: "restToNote",
          noteId: "",
          partId: target.partId,
          startBeat: formatFraction(target.startBeat),
          durationBeats: formatFraction(target.durationBeats),
          pitchMidi: pitchBefore(canonical, target.partId, target.startBeat),
        };
      },
      ja.commandFeedback.restConverted,
      () => {
        if (newNoteExportId) selectExportId(newNoteExportId, { scroll: true });
      },
    );
  }, [applyRhythmEdit, selectExportId]);

  const reviewUndo = useCallback(() => {
    const edit = session.undo();
    if (!edit) {
      announce(ja.review.feedback.nothingToUndo);
      return;
    }
    bumpDoc();
    if (edit.noteChanges.length > 0 || edit.docSwap != null) reloadEditedScore();
    reportInspector();
    announce(ja.review.feedback.undone);
  }, [session, bumpDoc, reloadEditedScore, reportInspector, announce]);

  const reviewRedo = useCallback(() => {
    const edit = session.redo();
    if (!edit) {
      announce(ja.review.feedback.nothingToRedo);
      return;
    }
    bumpDoc();
    if (edit.noteChanges.length > 0 || edit.docSwap != null) reloadEditedScore();
    reportInspector();
    announce(ja.review.feedback.redone);
  }, [session, bumpDoc, reloadEditedScore, reportInspector, announce]);

  /** 元音源を再生 — loop the issue's source range. The media transport is
   *  driven when a source is loaded (sourceControl); the score clock loop
   *  arms either way so the passage indication (LOOP_CLASS) shows which
   *  notes the audio range covers. */
  const playSource = useCallback(() => {
    const issue = issueAtCursor();
    if (!issue) return;
    let startSec = issue.timeRange?.startSec;
    let endSec = issue.timeRange?.endSec;
    if (startSec == null || endSec == null) {
      // No explicit range: loop the canonical note's notated span.
      const table = tableRef.current;
      const first = issue.canonicalNoteIds[0];
      const onset = first ? table?.onsetMsByCanonical.get(first) : undefined;
      if (!table || onset == null) return;
      startSec = onset / 1000;
      endSec = nearestOffset(table, onset) / 1000;
    }
    const clock = clockRef.current;
    clock?.setLoop({ startMs: startSec * 1000, endMs: endSec * 1000 });
    if (sourceControl) {
      sourceControl.setLoop({ start: startSec, end: endSec });
      sourceControl.seekTo(startSec);
      sourceControl.play();
    } else {
      clock?.seek(startSec * 1000);
      clock?.play();
    }
    announce(ja.review.feedback.playingSource);
  }, [issueAtCursor, sourceControl, announce]);

  /* --------------------------- controller -------------------------------- */

  useEffect(() => {
    if (!controllerRef) return;
    const controller: ScoreWorkspaceController = {
      zoomIn: () => changeZoom(zoomRef.current + SCORE_ZOOM_STEP_PCT),
      zoomOut: () => changeZoom(zoomRef.current - SCORE_ZOOM_STEP_PCT),
      zoomFit: () => zoomFit(),
      clearSelection: () => {
        if (reviewOpenRef.current) exitReview();
        else clearSelection();
      },
      togglePlayPause: () => clockRef.current?.togglePlayPause(),
      stop: () => clockRef.current?.stop(),
      seekToStart: () => clockRef.current?.seek(0),
      seekToEnd: () => {
        const c = clockRef.current;
        if (c) c.seek(c.durationMs());
      },
      jumpBy: (deltaMs) => clockRef.current?.jumpBy(deltaMs),
      toggleLoop: () => {
        const c = clockRef.current;
        if (!c) return;
        if (c.loopRange()) c.setLoop(null);
        else {
          // No waveform range selection yet (UI-020) — arm the loop over
          // the selected note's span when possible so Ctrl+L is honest.
          const sel = selectionRef.current;
          const table = tableRef.current;
          if (sel?.canonicalId && table) {
            const onset = table.onsetMsByCanonical.get(sel.canonicalId);
            if (onset != null) {
              const next = nearestOffset(table, onset);
              c.setLoop({ startMs: onset, endMs: next });
            }
          } else {
            c.setLoop({ startMs: 0, endMs: c.durationMs() });
          }
        }
      },
      // #113: expose the armed loop so the app can mirror it onto the
      // media transport (audio loops together with the score marks).
      loopRange: () => clockRef.current?.loopRange() ?? null,
      resumeFollow: () => resumeFollow(),
      setFollowEnabled: (on) => {
        if (on) resumeFollow();
        else {
          setFollowEnabled(false);
          followRef.current = false;
          suspendedRef.current = false;
          setFollowSuspended(false);
        }
      },
      // FEAT-001: audition toggle — driven from the transport bar.
      toggleAudition: () => {
        const synth = synthRef.current;
        if (!synth) return;
        const next = !auditionRef.current;
        auditionRef.current = next;
        setAuditionEnabled(next);
        synth.setEnabled(next);
        announce(
          next
            ? "楽譜の自動演奏をオンにしました"
            : "楽譜の自動演奏をオフにしました",
        );
      },
      openReview: () => openReview(),
      reviewNext: () => gotoIssue(reviewIndexRef.current + 1),
      reviewPrevious: () => gotoIssue(reviewIndexRef.current - 1),
      reviewAccept: () => reviewAccept(),
      reviewDismiss: () => reviewDismiss(),
      reviewPlaySource: () => playSource(),
      reviewPitch: (delta) => reviewPitch(delta),
      reviewDeleteOrRestore: () => reviewDeleteOrRestore(),
      exitReview: () => exitReview(),
      undo: () => reviewUndo(),
      redo: () => reviewRedo(),
      // #114: score-workspace navigation + direct note edits (spec 10/13).
      selectAdjacentNote: (direction) => selectAdjacentNote(direction),
      editSelectedPitch: (delta) => editSelectedPitch(delta),
      toggleSelectedDeleted: () => toggleSelectedDeleted(),
      toggleSelectedEnharmonic: () => toggleSelectedEnharmonic(),
      // #115: engine rhythm edits (spec 13) — duration ladder, onset
      // grid shift, tie toggle. Async internally; feedback announces.
      noteDurationScale: (power) => noteDurationScale(power),
      shiftSelectedOnset: (steps) => shiftSelectedOnset(steps),
      toggleSelectedTie: () => toggleSelectedTie(),
      setTempo: (bpm) => setTempo(bpm),
      setMeter: (bpm_, bu) => setMeter(bpm_, bu),
      setKey: (fifths) => setKey(fifths),
      requantize: (settings) => requantize(settings),
      splitSelectedNote: () => splitSelectedNote(),
      mergeSelectedNotes: () => mergeSelectedNotes(),
      convertSelectedRest: () => convertSelectedRest(),
    };
    controllerRef(controller);
    return () => controllerRef(null);
  }, [
    controllerRef,
    changeZoom,
    zoomFit,
    clearSelection,
    exitReview,
    resumeFollow,
    openReview,
    gotoIssue,
    reviewAccept,
    reviewDismiss,
    playSource,
    reviewPitch,
    reviewDeleteOrRestore,
    reviewUndo,
    reviewRedo,
    selectAdjacentNote,
    editSelectedPitch,
    toggleSelectedDeleted,
    toggleSelectedEnharmonic,
    noteDurationScale,
    shiftSelectedOnset,
    toggleSelectedTie,
    setTempo,
    setMeter,
    setKey,
    requantize,
    splitSelectedNote,
    mergeSelectedNotes,
    convertSelectedRest,
    announce,
  ]);



  /* --------------------------- state mirror ------------------------------ */

  useEffect(() => {
    onStateChange?.({
      hasSelection: selection !== null,
      // #163: a rest glyph is selected (canonicalId null + hs-rest id) —
      // gates the score.restToNote command.
      hasRestSelection:
        selection !== null &&
        selection.canonicalId === null &&
        restOrdinalOf(selection.exportId) !== null,
      isPlaying: clockSnap.isPlaying,
      loopEnabled: clockSnap.loop !== null,
      positionMs: clockSnap.positionMs,
      durationMs: clockSnap.durationMs,
      followEnabled,
      followSuspended,
      reviewOpen,
      zoomPct: zoom,
      canUndo: session.canUndo,
      canRedo: session.canRedo,
      openIssueCount: pendingCount,
      auditionEnabled,
    });
  }, [
    selection,
    clockSnap,
    followEnabled,
    followSuspended,
    reviewOpen,
    zoom,
    onStateChange,
    session,
    pendingCount,
    docVersion,
    auditionEnabled,
  ]);

  // Initial inspector = score summary (§22 "Nothing selected").
  useEffect(() => {
    if (!loading) reportInspector();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading]);

  /* ------------------------------- render -------------------------------- */

  const visiblePages =
    viewMode === "page" ? pages.filter((p) => p.page === currentPage) : pages;
  const s = ja.scoreView;

  if (initError) {
    return (
      <div className="hs-score-error" role="alert">
        <h2>{s.renderErrorTitle}</h2>
        <p>{initError}</p>
      </div>
    );
  }

  return (
    <div className="hs-score-workspace">
      <div className="hs-score-toolbar" role="toolbar" aria-label={s.regionLabel}>
        <SegmentedControl
          options={[
            { value: "continuous", label: s.continuous },
            { value: "page", label: s.page },
          ]}
          value={viewMode}
          onChange={(v) => changeViewMode(v)}
          ariaLabel={s.viewModeLabel}
        />
        {viewMode === "page" && pages.length > 1 && (
          <span className="hs-score-toolbar__pages">
            <HsButton
              size="small"
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              disabled={currentPage <= 1}
            >
              {s.prevPage}
            </HsButton>
            <span aria-live="polite">{s.pagePosition(currentPage, pages.length)}</span>
            <HsButton
              size="small"
              onClick={() => setCurrentPage((p) => Math.min(pages.length, p + 1))}
              disabled={currentPage >= pages.length}
            >
              {s.nextPage}
            </HsButton>
          </span>
        )}
        {pitch === "hornF" && (
          <span className="hs-score-toolbar__caption">
            {ja.pitch.hornF}（{ja.pitch.writtenNote}）
          </span>
        )}
        <span className="hs-score-toolbar__spacer" />
        <HsButton size="small" onClick={() => changeZoom(zoom - SCORE_ZOOM_STEP_PCT)}>
          {s.zoomOut}
        </HsButton>
        <span className="hs-score-toolbar__zoom" aria-live="polite" aria-label={s.zoomLabel}>
          {zoom}%
        </span>
        <HsButton size="small" onClick={() => changeZoom(zoom + SCORE_ZOOM_STEP_PCT)}>
          {s.zoomIn}
        </HsButton>
        <HsButton size="small" onClick={zoomFit}>
          {s.zoomFit}
        </HsButton>
      </div>

      {reviewOpen && (
        <ReviewBar
          index={Math.min(reviewIndex, Math.max(0, allIssues.length - 1))}
          total={allIssues.length}
          pending={pendingCount}
          issue={allIssues[reviewIndex] ?? null}
          copy={
            allIssues[reviewIndex]
              ? {
                  reasonTitle: copy.review.reasonTitle(
                    allIssues[reviewIndex].reason,
                  ),
                  reasonDetail: copy.review.reasonDetail(
                    allIssues[reviewIndex],
                  ),
                  severityLabel: copy.review.severityLabel(
                    allIssues[reviewIndex].severity,
                  ),
                  statusLabel: copy.review.statusLabel(
                    allIssues[reviewIndex].status,
                  ),
                }
              : null
          }
          noteDeleted={
            allIssues[reviewIndex]?.canonicalNoteIds[0] != null &&
            session.isDeleted(allIssues[reviewIndex].canonicalNoteIds[0])
          }
          canUndo={session.canUndo}
          canRedo={session.canRedo}
          actionLabel={(() => {
            const issue = allIssues[reviewIndex];
            if (!issue) return null;
            if (
              issue.evidence["suggestVoicesTexture"] === true &&
              onRetranscribeVoices
            ) {
              return ja.review.retranscribeVoices;
            }
            // #176: spelling issues resolve with the enharmonic toggle,
            // not the pitch +/- buttons (those change sounding pitch).
            if (issue.reason === "pitch_spelling_ambiguous") {
              return ja.commands.noteEnharmonic;
            }
            return null;
          })()}
          onAction={(() => {
            const issue = allIssues[reviewIndex];
            if (!issue) return undefined;
            if (issue.evidence["suggestVoicesTexture"] === true) {
              return onRetranscribeVoices ?? undefined;
            }
            if (issue.reason === "pitch_spelling_ambiguous") {
              return () => toggleSelectedEnharmonic();
            }
            return undefined;
          })()}
          onPrev={() => gotoIssue(reviewIndexRef.current - 1)}
          onNext={() => gotoIssue(reviewIndexRef.current + 1)}
          onPlaySource={playSource}
          onAccept={reviewAccept}
          onDismiss={reviewDismiss}
          onPitch={reviewPitch}
          onDeleteOrRestore={reviewDeleteOrRestore}
          onUndo={reviewUndo}
          onRedo={reviewRedo}
          onExit={exitReview}
        />
      )}

      {loading && <div className="hs-score-loading">{s.loading}</div>}
      {renderError && (
        <div className="hs-score-error" role="alert">
          <h2>{s.renderErrorTitle}</h2>
          <p>{s.renderErrorBody}</p>
          <HsButton onClick={() => renderScore(pitchRef.current)}>{ja.common.retry}</HsButton>
        </div>
      )}
      {!renderError && (
        <ScoreView
          ref={scrollRef}
          pages={visiblePages}
          onElementClick={(id) => selectExportId(id)}
          onBackgroundClick={clearSelection}
          onUserNavigate={suspendFollow}
          ariaLabel={s.regionLabel}
        />
      )}

      {followSuspended && (
        <div className="hs-score-follownote" role="status">
          <span>{s.followPaused}</span>
          <HsButton size="small" variant="primary" onClick={resumeFollow}>
            {s.resumeFollow}
          </HsButton>
        </div>
      )}
    </div>
  );
}

/** Offset ms for a canonical id — the next distinct onset after its own,
 *  or the document end. Used to arm a note-span loop. */
function nearestOffset(table: PlaybackTable, onsetMs: number): number {
  let best = Number.POSITIVE_INFINITY;
  for (const t of table.onsetMsByCanonical.values()) {
    if (t > onsetMs && t < best) best = t;
  }
  return Number.isFinite(best) ? best : table.durationMs;
}

/**
 * velocityByCanonicalId (#168): the audition carries the detected
 * dynamics. Velocity lives on the canonical payload's notes, not on the
 * MusicXML ParsedNote view, so the synth reads it from canonical truth.
 */
import { describe, expect, it } from "vitest";
import { velocityByCanonicalId } from "./playbackSynth";
import { bendsByCanonicalId } from "./playbackSynth";

function doc(parts: Record<string, unknown>[]): unknown {
  return { content: { parts } };
}

describe("velocityByCanonicalId", () => {
describe("bendsByCanonicalId", () => {
  it("maps each canonical note id to its normalized bend curve (#174)", () => {
    const d = doc([
      {
        id: "P1",
        notes: [
          {
            id: "sn-000001",
            pitchBends: [
              { timeSec: 0, bendSemitones: 0 },
              { timeSec: 0.5, bendSemitones: 0.5 },
              { timeSec: 1, bendSemitones: 0 },
            ],
          },
          { id: "sn-000002" }, // no bends
        ],
      },
    ]);
    const m = bendsByCanonicalId(d);
    expect(m.get("sn-000001")).toEqual([
      { pos: 0, semis: 0 },
      { pos: 0.5, semis: 0.5 },
      { pos: 1, semis: 0 },
    ]);
    expect(m.has("sn-000002")).toBe(false);
  });

  it("skips malformed points and payloads", () => {
    const d = doc([
      {
        id: "P1",
        notes: [
          { id: "sn-000001", pitchBends: [{ timeSec: "x" }] },
          { id: "sn-000002", pitchBends: "nope" },
        ],
      },
    ]);
    const m = bendsByCanonicalId(d);
    expect(m.size).toBe(0);
    expect(bendsByCanonicalId(null).size).toBe(0);
    expect(bendsByCanonicalId({}).size).toBe(0);
    expect(bendsByCanonicalId(doc([])).size).toBe(0);
  });
});

  it("maps each canonical note id to its velocity", () => {
    const d = doc([
      {
        id: "P1",
        notes: [
          { id: "sn-000001", velocity: 96 },
          { id: "sn-000002", velocity: 40 },
        ],
      },
      { id: "P2", notes: [{ id: "sn-000007", velocity: 110 }] },
    ]);
    const m = velocityByCanonicalId(d);
    expect(m.get("sn-000001")).toBe(96);
    expect(m.get("sn-000002")).toBe(40);
    expect(m.get("sn-000007")).toBe(110);
  });

  it("skips notes without a numeric velocity and malformed payloads", () => {
    const d = doc([
      {
        id: "P1",
        notes: [
          { id: "sn-000001" }, // no velocity
          { id: "sn-000002", velocity: "loud" }, // wrong type
          { velocity: 90 }, // no id
        ],
      },
    ]);
    const m = velocityByCanonicalId(d);
    expect(m.size).toBe(0);
    expect(velocityByCanonicalId(null).size).toBe(0);
    expect(velocityByCanonicalId({}).size).toBe(0);
    expect(velocityByCanonicalId(doc([])).size).toBe(0);
  });
});

/**
 * FEAT-001 (#60): 楽譜の自動演奏。
 *
 * `PlaybackTable`(Verovio timemap → canonical→ms)と `ParsedNote`(音高)
 * を結合し、WebAudio でスコアを発音する。`ScoreCursorClock` と同期し、
 * 追従カーソルと同じ位置で音が鳴る。
 *
 * 設計:
 * - 演奏は常に「コンサートピッチ(実音)」。hornF 表示中も実音で鳴らす
 *   (採譜の確認用途に合わせる。記譜音で鳴らすと半音ズレて混乱する)。
 * - 音色は簡易のトライアングル+サインを重ねた「ホルン風」の柔らかい音。
 *   外部音源/サウンドフォントには依存しない(offline 方針)。
 * - `ScoreCursorClock` の `subscribe` でスナップショットを受け、
 *   再生中は rAF ではなく WebAudio の oscillator を事前スケジューリング
 *   する方式で、UIスレッド負荷を抑える。
 * - ループがアームされている間はその範囲を繰り返しスケジュールする。
 * - `rate` 変更は既スケジュールを破棄して再計算する。
 */
import type { PlaybackTable } from "./playbackTable";
import type { ParsedNote } from "./scoreDoc";

/** canonical id → 音高。step/alter/octave から MIDI note を計算する。 */
const STEP_TO_SEMITONE: Record<string, number> = {
  C: 0,
  D: 2,
  E: 4,
  F: 5,
  G: 7,
  A: 9,
  B: 11,
};

function noteToMidi(note: ParsedNote): number | null {
  if (note.isRest || note.step === undefined || note.octave === undefined) {
    return null;
  }
  const base = STEP_TO_SEMITONE[note.step];
  if (base === undefined) return null;
  // MIDI: C4 = 60
  return base + (note.alter ?? 0) + (note.octave + 1) * 12;
}

function midiToFreq(midi: number): number {
  return 440 * Math.pow(2, (midi - 69) / 12);
}

/** スケジュール対象の 1 音。 */
interface ScheduledNote {
  startMs: number;
  endMs: number;
  freq: number;
  /** MIDI velocity 0-127 (null = unknown -> default loudness). #168 */
  velocity: number | null;
  /** Normalized bend curve (pos 0..1, semitones) for vibrato. #174 */
  bends: readonly { pos: number; semis: number }[];
}

/**
 * canonicalId -> MIDI velocity, read off the canonical payload's
 * content.parts[].notes[].velocity (#168). The MusicXML ParsedNote view
 * does not carry velocity, so the audition pulls it from canonical truth.
 */
export function velocityByCanonicalId(
  canonicalDocument: unknown,
): Map<string, number> {
  const doc = canonicalDocument as Record<string, unknown> | null;
  const content = doc?.["content"] as Record<string, unknown> | undefined;
  const parts = content?.["parts"];
  const map = new Map<string, number>();
  if (!Array.isArray(parts)) return map;
  for (const rawPart of parts) {
    const notes = (rawPart as Record<string, unknown>)["notes"];
    if (!Array.isArray(notes)) continue;
    for (const rawNote of notes) {
      const n = rawNote as Record<string, unknown>;
      const id = n["id"];
      const v = n["velocity"];
      if (typeof id === "string" && typeof v === "number") {
        map.set(id, v);
      }
    }
  }
  return map;
}

/**
 * canonicalId -> normalized bend curve, read off the canonical payload's
 * content.parts[].notes[].pitchBends (#174). Each point's timeSec is the
 * fractional position inside the note (0..1), bendSemitones the offset.
 */
export function bendsByCanonicalId(
  canonicalDocument: unknown,
): Map<string, readonly { pos: number; semis: number }[]> {
  const doc = canonicalDocument as Record<string, unknown> | null;
  const content = doc?.["content"] as Record<string, unknown> | undefined;
  const parts = content?.["parts"];
  const map = new Map<string, readonly { pos: number; semis: number }[]>();
  if (!Array.isArray(parts)) return map;
  for (const rawPart of parts) {
    const notes = (rawPart as Record<string, unknown>)["notes"];
    if (!Array.isArray(notes)) continue;
    for (const rawNote of notes) {
      const n = rawNote as Record<string, unknown>;
      const id = n["id"];
      const bends = n["pitchBends"];
      if (typeof id !== "string" || !Array.isArray(bends)) continue;
      const curve = bends
        .map((b) => {
          const p = (b as Record<string, unknown>)["timeSec"];
          const s = (b as Record<string, unknown>)["bendSemitones"];
          return typeof p === "number" && typeof s === "number"
            ? { pos: p, semis: s }
            : null;
        })
        .filter((x): x is { pos: number; semis: number } => x !== null);
      if (curve.length > 0) map.set(id, curve);
    }
  }
  return map;
}

export interface ScoreSynthOptions {
  /** AudioContext は外部注入可(テスト/既存コンテキスト共有)。 */
  audioContext?: AudioContext | null;
  /** 音量 0–1。 */
  volume?: number;
}

/**
 * 楽譜の発音エンジン。`ScoreCursorClock` に追従するので、UI の再生位置
 * と同期した「楽譜が鳴る」体験を提供する。
 */
export class ScorePlaybackSynth {
  private ctx: AudioContext | null;
  private master: GainNode | null = null;
  private notes: ScheduledNote[] = [];
  private scheduledNodes: OscillatorNode[] = [];
  private loopRangeMs: { startMs: number; endMs: number } | null = null;
  private rate = 1;
  private enabled = false;
  private disposeRequested = false;
  private scheduleTimer: ReturnType<typeof setTimeout> | null = null;
  private cursorMs = 0;
  private playing = false;
  private volume: number;
  /** ここまでの score 時間は発音済みスケジュール済み(重複防止の
   *  ウォーターマーク)。シーク/レート変更/再生開始でリセットする。 */
  private scheduledUntilMs = 0;
  /** ティック間の実経過計測用。 */
  private lastTickAt = 0;

  /** 事前スケジュールの先読み幅(ms 相当の score 時間)。 */
  private readonly LOOKAHEAD_MS = 400;
  /** スケジュールの走査間隔。 */
  private readonly TICK_MS = 80;

  constructor(opts: ScoreSynthOptions = {}) {
    this.ctx = opts.audioContext ?? null;
    this.volume = opts.volume ?? 0.5;
  }

  /**
   * 再生するノート列をロードする。
   * `table` は Verovio timemap 由来、`notesByCanonical` は concert
   * presentation の ParsedNote マップ(実音で鳴らすため horn 側は使わない)。
   */
  load(
    table: PlaybackTable,
    notesByCanonical: ReadonlyMap<string, readonly ParsedNote[]>,
    velocities?: ReadonlyMap<string, number>,
    bends?: ReadonlyMap<string, readonly { pos: number; semis: number }[]>,
  ): void {
    const notes: ScheduledNote[] = [];
    for (const seg of table.segments) {
      for (const canonicalId of seg.canonicalIds) {
        const frags = notesByCanonical.get(canonicalId);
        if (!frags) continue;
        for (const frag of frags) {
          const midi = noteToMidi(frag);
          if (midi === null) continue;
          notes.push({
            startMs: seg.startMs,
            endMs: seg.endMs,
            freq: midiToFreq(midi),
            velocity: velocities?.get(canonicalId) ?? null,
            bends: bends?.get(canonicalId) ?? [],
          });
          // 和音: chord メンバーは同じ onset を持つので、同じセグメントで
          // 別 ParsedNote として既に処理済み(frag 毎に 1 音追加)。
        }
      }
    }
    // onset 順 + 同時は周波数順で安定化。
    notes.sort((a, b) => a.startMs - b.startMs || a.freq - b.freq);
    this.notes = notes;
  }

  /** スコアクロックの位置(ms)を同期する。シーク/レート変更に追従。 */
  sync(positionMs: number, isPlaying: boolean, rate: number): void {
    const wasPlaying = this.playing;
    const rateChanged = rate !== this.rate;
    // シーク/ループ折り返し検出: 内部カーソルと大きくズレたら
    // スケジュール済み音声を破棄して新位置から張り直す。
    // ティックの setTimeout ドリフトが 10Hz のスナップショット同期までに
    // 250ms を超え得るので、誤検出を避けるため余裕を持たせる。
    const jumped = Math.abs(positionMs - this.cursorMs) > 400;
    this.cursorMs = positionMs;
    this.playing = isPlaying;
    this.rate = rate;
    if (isPlaying && !wasPlaying) {
      this.scheduledUntilMs = positionMs;
      // 再生開始: 現在位置から先読みスケジュールを開始。
      this.scheduleFromCursor();
    } else if (!isPlaying && wasPlaying) {
      // 一時停止: 鳴っている音を止める。
      this.stopAllVoices();
      this.stopTimer();
    } else if (isPlaying && this.enabled && (rateChanged || jumped)) {
      // レート変更やシーク: スケジュール済みの音は旧基準なので張り直す。
      this.stopAllVoices();
      this.scheduledUntilMs = positionMs;
      this.scheduleFromCursor();
    }
  }

  /** ループ範囲の同期(ScoreCursorClock の loop)。 */
  setLoop(range: { startMs: number; endMs: number } | null): void {
    this.loopRangeMs = range;
  }

  /** 演奏モードのオン/オフ。 */
  setEnabled(on: boolean): void {
    this.enabled = on;
    if (!on) {
      this.stopAllVoices();
      this.stopTimer();
    } else if (this.playing) {
      this.scheduledUntilMs = this.cursorMs;
      this.scheduleFromCursor();
    }
  }

  isEnabled(): boolean {
    return this.enabled;
  }

  setVolume(v: number): void {
    this.volume = Math.min(1, Math.max(0, v));
    if (this.master) this.master.gain.value = this.volume;
  }

  dispose(): void {
    this.disposeRequested = true;
    this.stopTimer();
    this.stopAllVoices();
    // AudioContext は外部共有の可能性があるので close はしない。
  }

  /* ------------------------------ internals ------------------------------ */

  private ensureContext(): AudioContext | null {
    if (this.ctx) return this.ctx;
    const Ctor: typeof AudioContext | undefined =
      globalThis.AudioContext ??
      (globalThis as { webkitAudioContext?: typeof AudioContext })
        .webkitAudioContext;
    if (!Ctor) return null;
    this.ctx = new Ctor();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.volume;
    this.master.connect(this.ctx.destination);
    return this.ctx;
  }

  /** カーソル位置から LOOKAHEAD_MS 先までの音をスケジュールする。 */
  private scheduleFromCursor(): void {
    const ctx = this.ensureContext();
    if (!ctx || !this.master || this.notes.length === 0) return;
    this.stopTimer();

    // AudioContext の currentTime を基準に、スコア時間 → 実時間に変換する。
    // scoreMs = cursorMs から、実時間 t0 = ctx.currentTime + 少しの猶予。
    const t0 = ctx.currentTime + 0.06; // 60ms の起動猶予
    const rate = this.rate;
    const windowStart = this.cursorMs;
    const windowEnd = windowStart + this.LOOKAHEAD_MS * rate;
    // ティック毎にウィンドウが重なるので、既にスケジュール済みの範囲
    // (scheduledUntilMs 以前)は二度鳴らさない。
    const scheduleFrom = Math.max(windowStart, this.scheduledUntilMs);

    for (const note of this.notes) {
      // 進行中の音(note.startMs < cursor)は既に鳴っているはずだが、
      // シーク直後の整合のため、onset がウィンドウ内にあるものだけ鳴らす。
      if (note.endMs <= windowStart) continue;
      if (note.startMs >= windowEnd) break;
      // onset が過去/スケジュール済みの音は次回 onset を待つ。
      if (note.startMs < scheduleFrom) continue;
      const startSec = t0 + (note.startMs - windowStart) / rate / 1000;
      const durSec = Math.max(0.04, (note.endMs - note.startMs) / rate / 1000);
      this.spawnVoice(note.freq, startSec, durSec, note.velocity, note.bends);
    }
    this.scheduledUntilMs = Math.max(this.scheduledUntilMs, windowEnd);
    this.lastTickAt = performance.now();

    // ループ: 範囲の終わりに近づいたらループ先頭から再スケジュール。
    if (this.loopRangeMs) {
      const { startMs, endMs } = this.loopRangeMs;
      if (this.cursorMs >= startMs && this.cursorMs < endMs) {
        const untilLoopEnd = (endMs - this.cursorMs) / rate;
        // ループ末尾の少し前に次周の先読みを仕掛ける。
        const nextTickMs = Math.max(
          this.TICK_MS,
          Math.min(untilLoopEnd * 1000 - 150, this.TICK_MS),
        );
        this.scheduleTimer = setTimeout(() => this.onTick(), nextTickMs);
        return;
      }
    }
    this.scheduleTimer = setTimeout(() => this.onTick(), this.TICK_MS);
  }

  private onTick(): void {
    if (this.disposeRequested || !this.enabled || !this.playing) return;
    // 実経過でカーソルを進める(setTimeout は遅延するので TICK_MS 固定
    // だと徐々に遅れる)。クロック subscribe が 10Hz で補正もする。
    const now = performance.now();
    const elapsedMs = (now - this.lastTickAt) * this.rate;
    this.cursorMs += elapsedMs;
    if (this.loopRangeMs) {
      const { startMs, endMs } = this.loopRangeMs;
      if (this.cursorMs >= endMs) {
        const span = endMs - startMs;
        this.cursorMs = startMs + ((this.cursorMs - startMs) % span);
        // ループ折り返し: 先読み済み範囲を巻き戻して再スケジュール。
        this.scheduledUntilMs = this.cursorMs;
      }
    }
    this.scheduleFromCursor();
  }

  /** 1 音を鳴らす。ホルンらしい柔らかさのため三角波+正弦波の 2 音構成。 */
  private spawnVoice(
    freq: number,
    startSec: number,
    durSec: number,
    velocity: number | null = null,
    bends: readonly { pos: number; semis: number }[] = [],
  ): void {
    const ctx = this.ctx;
    const master = this.master;
    if (!ctx || !master) return;

    const osc1 = ctx.createOscillator();
    osc1.type = "triangle";
    osc1.frequency.value = freq;
    const osc2 = ctx.createOscillator();
    osc2.type = "sine";
    osc2.frequency.value = freq * 0.5; // サブオクターブで厚みを出す
    const osc2Gain = ctx.createGain();
    osc2Gain.gain.value = 0.25;
    // #174: ride the performed bend curve (vibrato/portamento). Each
    // point's pos is a fraction of the note's span; both oscillators
    // follow the same semitone offset (freq * 2^(semis/12)).
    if (bends.length > 0) {
      osc1.frequency.setValueAtTime(freq, startSec);
      osc2.frequency.setValueAtTime(freq * 0.5, startSec);
      for (const b of bends) {
        const t = startSec + Math.min(1, Math.max(0, b.pos)) * durSec;
        const f1 = freq * Math.pow(2, b.semis / 12);
        osc1.frequency.linearRampToValueAtTime(f1, t);
        osc2.frequency.linearRampToValueAtTime(f1 * 0.5, t);
      }
      // Return to the written pitch at the note's end.
      osc1.frequency.linearRampToValueAtTime(freq, startSec + durSec);
      osc2.frequency.linearRampToValueAtTime(freq * 0.5, startSec + durSec);
    }

    const env = ctx.createGain();
    // ADSR 風: 5ms attack, sustain, 40ms release。
    // #168: scale the sustain peak by the note's velocity so the audition
    // carries the detected dynamics (matches the MIDI export's note_on).
    const peak =
      velocity != null
        ? 0.2 + 0.7 * (Math.min(127, Math.max(0, velocity)) / 127)
        : 0.9;
    env.gain.setValueAtTime(0, startSec);
    env.gain.linearRampToValueAtTime(peak, startSec + 0.005);
    env.gain.setValueAtTime(peak, startSec + Math.max(0.005, durSec - 0.04));
    env.gain.linearRampToValueAtTime(0, startSec + durSec);

    osc1.connect(env);
    osc2.connect(osc2Gain);
    osc2Gain.connect(env);
    env.connect(master);

    osc1.start(startSec);
    osc2.start(startSec);
    osc1.stop(startSec + durSec + 0.02);
    osc2.stop(startSec + durSec + 0.02);
    this.scheduledNodes.push(osc1, osc2);
    // 鳴り終わったノードを配列から外す(長時間再生で無限に増えないよう)。
    const drop = () => {
      this.scheduledNodes = this.scheduledNodes.filter(
        (n) => n !== osc1 && n !== osc2,
      );
    };
    osc1.onended = drop;
  }

  private stopAllVoices(): void {
    const ctx = this.ctx;
    if (!ctx) return;
    const now = ctx.currentTime;
    for (const osc of this.scheduledNodes) {
      try {
        osc.stop(now);
      } catch {
        /* already stopped */
      }
      osc.disconnect();
    }
    this.scheduledNodes = [];
  }

  private stopTimer(): void {
    if (this.scheduleTimer) {
      clearTimeout(this.scheduleTimer);
      this.scheduleTimer = null;
    }
  }
}

"""Canonical score model (FND-001).

A ScoreDocument is *concert pitch only*. Horn in F is a derived presentation
of the same canonical notes and therefore shares canonical note IDs.

Timing model: score positions are rational beat positions (Fraction), never
float seconds. Source seconds are reachable only through the tempo map /
provenance layer.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from enum import Enum
from fractions import Fraction
from itertools import pairwise
from typing import Any

from hornscribe.domain.events import PitchBendPoint
from hornscribe.domain.ids import (
    ProjectId,
    RawNoteEventId,
    ScoreNoteId,
    ScoreRevisionId,
    derive_score_revision_id,
)


class PitchSpace(Enum):
    """The only pitch space allowed for canonical storage is CONCERT."""

    CONCERT = "concert"
    WRITTEN_HORN_F = "written_horn_f"  # presentation/export only, never canonical


@dataclass(frozen=True)
class ScoreAtom:
    """One written symbol inside a canonical note or rest (QNT-006).

    ``duration_beats`` is the atom's exact span on the canonical beat axis;
    ``symbol`` + ``dots`` + ``tuplet`` describe how it is written. These are
    the quantizer's committed notation decisions — HSQ decides the written
    decomposition, the notation layer only renders it (architecture rule:
    music21 realizes/serializes, never re-quantizes).

    ``tie_to_next`` joins this atom to the following atom *inside the same
    canonical note's* atom list; it is always ``False`` on a note's last atom
    and always ``False`` on rest atoms (rests never tie).
    """

    duration_beats: Fraction
    """Exact span of the written symbol (e.g. a triplet eighth = 1/3 beat in
    a quarter-note-beat meter)."""
    symbol: str
    """Base symbol name: ``"whole"``, ``"half"``, ``"quarter"``, ``"eighth"``,
    ``"sixteenth"``, ``"32nd"``, ``"64th"``."""
    dots: int = 0
    tuplet: str | None = None
    """Tuplet label (``"triplet"`` in HSQ-v1), or ``None`` for binary atoms."""
    tuplet_group_start: bool = False
    """``True`` when this atom opens a new visual tuplet group (MusicXML
    ``<tuplet type="start">``); the last tuplet atom before the next
    ``tuplet_group_start``/non-tuplet atom closes it."""
    tie_to_next: bool = False

    def __post_init__(self) -> None:
        object.__setattr__(self, "duration_beats", _unfrac(self.duration_beats))
        if self.duration_beats <= 0:
            raise ValueError(f"atom duration_beats must be > 0, got {self.duration_beats}")
        if not self.symbol:
            raise ValueError("atom symbol must be a non-empty string")
        if (
            isinstance(self.dots, bool)
            or not isinstance(self.dots, int)
            or not 0 <= self.dots <= 2
        ):
            raise ValueError(f"atom dots must be in 0..2, got {self.dots!r}")
        if self.tuplet is not None and not self.tuplet:
            raise ValueError("atom tuplet must be None or a non-empty label")
        if self.tuplet_group_start and self.tuplet is None:
            raise ValueError("tuplet_group_start requires a tuplet atom")

    def to_dict(self) -> dict[str, Any]:
        return {
            "durationBeats": _frac(self.duration_beats),
            "symbol": self.symbol,
            "dots": self.dots,
            "tuplet": self.tuplet,
            "tupletGroupStart": self.tuplet_group_start,
            "tieToNext": self.tie_to_next,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreAtom:
        return cls(
            duration_beats=_unfrac(data["durationBeats"]),
            symbol=str(data["symbol"]),
            dots=int(data.get("dots", 0)),
            tuplet=data.get("tuplet"),
            tuplet_group_start=bool(data.get("tupletGroupStart", False)),
            tie_to_next=bool(data.get("tieToNext", False)),
        )


@dataclass(frozen=True)
class ScoreRest:
    """A realized rest span: start position plus its written rest atoms.

    Rests carry no canonical identity (``ids.py``: rest ``note/@id`` values
    are presentation-only). The atoms tile ``[start_beat, start_beat +
    total)`` exactly, never tie, and never cross a barline — a multi-measure
    rest span contains one atom group per measure (a complete empty measure
    is a single ``"whole"`` atom = the measure-rest convention).
    """

    start_beat: Fraction
    atoms: tuple[ScoreAtom, ...]

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(self, "atoms", tuple(self.atoms))
        if self.start_beat < 0:
            raise ValueError(f"rest start_beat must be >= 0, got {self.start_beat}")
        if not self.atoms:
            raise ValueError("a rest span needs at least one atom")
        for atom in self.atoms:
            if not isinstance(atom, ScoreAtom):
                raise TypeError(f"expected ScoreAtom, got {atom!r}")
            if atom.tie_to_next:
                raise ValueError("rest atoms cannot tie to the next atom")

    @property
    def duration_beats(self) -> Fraction:
        """Total exact span covered by the rest atoms."""
        return sum((a.duration_beats for a in self.atoms), Fraction(0))

    @property
    def end_beat(self) -> Fraction:
        """End of the rest span (exclusive)."""
        return self.start_beat + self.duration_beats

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "atoms": [a.to_dict() for a in self.atoms],
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreRest:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            atoms=tuple(ScoreAtom.from_dict(a) for a in data.get("atoms", ())),
        )


@dataclass(frozen=True)
class QuantizedNote:
    """A canonical score note in rational beat positions.

    ``atoms`` is the optional written decomposition committed by the
    quantizer (QNT-006): when present it tiles ``duration_beats`` exactly,
    every atom but the last carries ``tie_to_next``, and no atom crosses a
    barline (barline/beat splits are already materialized as separate tied
    atoms). When empty the notation layer falls back to deriving the written
    decomposition itself (legacy/provisional scores).
    """

    id: ScoreNoteId
    source_event_ids: tuple[RawNoteEventId, ...]
    pitch_midi: int
    start_beat: Fraction
    duration_beats: Fraction
    velocity: int | None = None
    tie_start: bool = False
    tie_stop: bool = False
    atoms: tuple[ScoreAtom, ...] = ()
    # #174: performed pitch-bend curve carried from the backend evidence,
    # normalized to this note's span (PitchBendPoint.time_sec = 0..1).
    # Omitted from serialization when empty so older payloads keep their
    # content-derived revision ids.
    pitch_bends: tuple[PitchBendPoint, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(self, "duration_beats", _unfrac(self.duration_beats))
        object.__setattr__(self, "atoms", tuple(self.atoms))
        object.__setattr__(self, "pitch_bends", tuple(self.pitch_bends))
        if self.start_beat < 0:
            raise ValueError(f"start_beat must be >= 0, got {self.start_beat}")
        if self.duration_beats <= 0:
            raise ValueError(f"duration_beats must be > 0, got {self.duration_beats}")
        if self.atoms:
            for atom in self.atoms:
                if not isinstance(atom, ScoreAtom):
                    raise TypeError(f"expected ScoreAtom, got {atom!r}")
            total = sum((a.duration_beats for a in self.atoms), Fraction(0))
            if total != self.duration_beats:
                raise ValueError(
                    f"note atoms total {total} != duration_beats {self.duration_beats}"
                )
            if self.atoms[-1].tie_to_next:
                raise ValueError("a note's last atom cannot tie_to_next")
            for atom in self.atoms[:-1]:
                if not atom.tie_to_next:
                    raise ValueError(
                        "interior atoms of a note must tie to the next atom "
                        "(an untied boundary would read as two notes)"
                    )

    @property
    def end_beat(self) -> Fraction:
        """End of the note span (exclusive)."""
        return self.start_beat + self.duration_beats

    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "id": str(self.id),
            "sourceEventIds": [str(e) for e in self.source_event_ids],
            "pitchMidi": self.pitch_midi,
            "startBeat": _frac(self.start_beat),
            "durationBeats": _frac(self.duration_beats),
            "velocity": self.velocity,
            "tieStart": self.tie_start,
            "tieStop": self.tie_stop,
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs (content-derived identity, ids.py).
        if self.atoms:
            data["atoms"] = [a.to_dict() for a in self.atoms]
        if self.pitch_bends:
            data["pitchBends"] = [b.to_dict() for b in self.pitch_bends]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> QuantizedNote:
        return cls(
            id=ScoreNoteId(data["id"]),
            source_event_ids=tuple(RawNoteEventId(e) for e in data.get("sourceEventIds", ())),
            pitch_midi=int(data["pitchMidi"]),
            start_beat=_unfrac(data["startBeat"]),
            duration_beats=_unfrac(data["durationBeats"]),
            velocity=data.get("velocity"),
            tie_start=bool(data.get("tieStart", False)),
            tie_stop=bool(data.get("tieStop", False)),
            atoms=tuple(ScoreAtom.from_dict(a) for a in data.get("atoms", ())),
            pitch_bends=tuple(
                PitchBendPoint.from_dict(b) for b in data.get("pitchBends", ())
            ),
        )


@dataclass(frozen=True)
class TempoSegment:
    start_beat: Fraction
    bpm: float

    def to_dict(self) -> dict[str, Any]:
        return {"startBeat": _frac(self.start_beat), "bpm": self.bpm}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TempoSegment:
        return cls(start_beat=_unfrac(data["startBeat"]), bpm=float(data["bpm"]))


@dataclass(frozen=True)
class TimeSignature:
    beats_per_measure: int
    beat_unit: int

    def to_dict(self) -> dict[str, Any]:
        return {"beatsPerMeasure": self.beats_per_measure, "beatUnit": self.beat_unit}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TimeSignature:
        return cls(
            beats_per_measure=int(data["beatsPerMeasure"]),
            beat_unit=int(data["beatUnit"]),
        )


@dataclass(frozen=True)
class KeySignature:
    """Fifths (-7..7) plus mode."""

    fifths: int
    mode: str = "major"

    def to_dict(self) -> dict[str, Any]:
        return {"fifths": self.fifths, "mode": self.mode}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> KeySignature:
        return cls(fifths=int(data["fifths"]), mode=str(data.get("mode", "major")))


@dataclass(frozen=True)
class KeyChange:
    """A key-signature boundary on the canonical beat axis (#133).

    The key_signature is active from start_beat until the next
    change's start_beat (or indefinitely for the last change) —
    the key-map analogue of MeterChange, without a phase concept
    (keys do not affect measure layout).
    """

    start_beat: Fraction
    key_signature: KeySignature

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        if self.start_beat < 0:
            raise ValueError(
                f"key change start_beat must be >= 0, got {self.start_beat}"
            )

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "keySignature": self.key_signature.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> KeyChange:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            key_signature=KeySignature.from_dict(data["keySignature"]),
        )


@dataclass(frozen=True)
class MeterChange:
    """A meter segment boundary on the canonical beat axis (QNT-006).

    The meter ``time_signature`` is active from ``start_beat`` until the
    next change's ``start_beat`` (or indefinitely for the last change).
    ``measure_phase_beats`` is the metrical offset of ``start_beat`` inside
    its measure cycle — the mid-piece analogue of ``pickup_beats``: ``0``
    means the change lands on a downbeat; ``p > 0`` means the segment's
    first measure covers only its last ``measure_length - p`` beats.
    """

    start_beat: Fraction
    time_signature: TimeSignature
    measure_phase_beats: Fraction = Fraction(0)

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(
            self, "measure_phase_beats", _unfrac(self.measure_phase_beats)
        )
        if self.start_beat < 0:
            raise ValueError(f"meter change start_beat must be >= 0, got {self.start_beat}")
        if self.measure_phase_beats < 0:
            raise ValueError(
                f"measure_phase_beats must be >= 0, got {self.measure_phase_beats}"
            )
        # The upper bound (phase < measure length) needs the canonical beat
        # unit, which only the owning ScoreRevisionPayload knows — it is
        # validated there.

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "timeSignature": self.time_signature.to_dict(),
            "measurePhaseBeats": _frac(self.measure_phase_beats),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> MeterChange:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            time_signature=TimeSignature.from_dict(data["timeSignature"]),
            measure_phase_beats=_unfrac(data.get("measurePhaseBeats", "0/1")),
        )


@dataclass(frozen=True)
class Part:
    """A single staff part containing canonical notes in score order.

    ``rests`` is the committed rest list (QNT-006): when non-empty the
    notation layer renders exactly these rest atoms and requires notes+rests
    to tile every measure — no gap-filling. When empty (legacy/provisional
    scores) the notation layer fills inter-note gaps itself.
    """

    id: str
    name: str
    notes: tuple[QuantizedNote, ...] = field(default_factory=tuple)
    rests: tuple[ScoreRest, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        object.__setattr__(self, "notes", tuple(self.notes))
        object.__setattr__(self, "rests", tuple(self.rests))
        ordered = sorted(self.rests, key=lambda r: r.start_beat)
        if tuple(ordered) != self.rests:
            raise ValueError("part rests must be in start_beat order")
        for prev, cur in pairwise(self.rests):
            if cur.start_beat < prev.end_beat:
                raise ValueError(
                    f"overlapping rests: {prev.start_beat}+{prev.duration_beats} "
                    f"vs {cur.start_beat}"
                )

    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "id": self.id,
            "name": self.name,
            "notes": [n.to_dict() for n in self.notes],
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs.
        if self.rests:
            data["rests"] = [r.to_dict() for r in self.rests]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Part:
        return cls(
            id=str(data["id"]),
            name=str(data["name"]),
            notes=tuple(QuantizedNote.from_dict(n) for n in data.get("notes", ())),
            rests=tuple(ScoreRest.from_dict(r) for r in data.get("rests", ())),
        )


def _frac(value: Fraction) -> str:
    return f"{value.numerator}/{value.denominator}"


def _unfrac(value: Any) -> Fraction:
    if isinstance(value, Fraction):
        return value
    if isinstance(value, str):
        return Fraction(value)
    return Fraction(value)


@dataclass(frozen=True)
class ScoreRevisionPayload:
    """The canonical content a score revision ID is derived from.

    Anything that changes the *musical content* of the score belongs here so
    that revision IDs track content, not serialization accidents.

    ``meter_changes`` is the full ordered meter map when the piece changes
    meter (QNT-006); when present it is authoritative for measure layout,
    its first entry must sit at beat ``0`` with ``time_signature`` matching
    the payload's own ``time_signature`` field, and its first
    ``measure_phase_beats`` must agree with ``pickup_beats``. When empty,
    layout derives from ``time_signature`` + ``pickup_beats`` alone (the
    single-meter legacy path).
    """

    tempo_map: tuple[TempoSegment, ...]
    time_signature: TimeSignature
    key_signature: KeySignature
    pickup_beats: Fraction
    parts: tuple[Part, ...]
    quantization_settings: dict[str, Any]
    meter_changes: tuple[MeterChange, ...] = ()
    """#133: key-signature boundaries — mirrors meter_changes (first
    entry at beat 0 carrying the payload key_signature, strictly
    increasing starts). Empty = single-key legacy path."""
    key_changes: tuple[KeyChange, ...] = ()
    """#134: detected swing feel — the offbeat phase (fraction of a
    notated beat) the piece swings to, e.g. 2/3 for a hard shuffle.
    None = straight. Notation renders a swing direction + playback
    hint; the written rhythm itself is left alone."""
    swing_feel: Fraction | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "tempo_map", tuple(self.tempo_map))
        object.__setattr__(self, "parts", tuple(self.parts))
        object.__setattr__(self, "meter_changes", tuple(self.meter_changes))
        object.__setattr__(self, "key_changes", tuple(self.key_changes))
        object.__setattr__(self, "pickup_beats", _unfrac(self.pickup_beats))
        if self.swing_feel is not None:
            object.__setattr__(self, "swing_feel", _unfrac(self.swing_feel))
            if not (Fraction(0) < self.swing_feel < Fraction(1)):
                raise ValueError(
                    f"swing_feel must be a beat fraction in (0, 1), got "
                    f"{self.swing_feel}"
                )
        if self.pickup_beats < 0:
            raise ValueError(f"pickup_beats must be >= 0, got {self.pickup_beats}")
        ts0 = self.time_signature
        if ts0.beats_per_measure <= 0 or ts0.beat_unit <= 0:
            raise ValueError(
                f"invalid time signature: {ts0.beats_per_measure}/{ts0.beat_unit}"
            )
        if self.key_changes:
            if self.key_changes[0].start_beat != 0:
                raise ValueError(
                    "first key change must start at beat 0, got "
                    f"{self.key_changes[0].start_beat}"
                )
            if self.key_changes[0].key_signature != self.key_signature:
                raise ValueError(
                    "first key change must carry the payload key_signature: "
                    f"{self.key_changes[0].key_signature} != {self.key_signature}"
                )
            for prev_key, cur_key in pairwise(self.key_changes):
                if cur_key.start_beat <= prev_key.start_beat:
                    raise ValueError(
                        "key changes must be strictly increasing: "
                        f"{prev_key.start_beat} !< {cur_key.start_beat}"
                    )
        if not self.meter_changes:
            # Legacy single-meter path: pickup must fit inside a measure of
            # the (beat-defining) first time signature.
            if self.pickup_beats >= ts0.beats_per_measure:
                raise ValueError(
                    f"pickup_beats {self.pickup_beats} must be shorter than a "
                    f"{ts0.beats_per_measure}-beat measure"
                )
            return
        first = self.meter_changes[0]
        if first.start_beat != 0:
            raise ValueError(
                f"first meter change must start at beat 0, got {first.start_beat}"
            )
        if first.time_signature != ts0:
            raise ValueError(
                "first meter change must carry the payload time_signature: "
                f"{first.time_signature} != {ts0}"
            )
        beat_ql = Fraction(4, ts0.beat_unit)
        expected_phase = (
            Fraction(ts0.beats_per_measure) - self.pickup_beats
            if self.pickup_beats > 0
            else Fraction(0)
        )
        if first.measure_phase_beats != expected_phase:
            raise ValueError(
                f"first meter change phase {first.measure_phase_beats} "
                f"disagrees with pickup_beats {self.pickup_beats} "
                f"(expected {expected_phase})"
            )
        for prev, cur in pairwise(self.meter_changes):
            if cur.start_beat <= prev.start_beat:
                raise ValueError(
                    "meter changes must be strictly increasing: "
                    f"{prev.start_beat} !< {cur.start_beat}"
                )
        for change in self.meter_changes:
            mlen = measure_length_beats(change.time_signature, beat_ql)
            if change.measure_phase_beats >= mlen:
                raise ValueError(
                    f"meter change at {change.start_beat} has phase "
                    f"{change.measure_phase_beats} >= measure length {mlen}"
                )
    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "tempoMap": [t.to_dict() for t in self.tempo_map],
            "timeSignature": self.time_signature.to_dict(),
            "keySignature": self.key_signature.to_dict(),
            "pickupBeats": _frac(self.pickup_beats),
            "parts": [p.to_dict() for p in self.parts],
            "quantizationSettings": self.quantization_settings,
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs.
        if self.meter_changes:
            data["meterChanges"] = [m.to_dict() for m in self.meter_changes]
        if self.key_changes:
            data["keyChanges"] = [k.to_dict() for k in self.key_changes]
        if self.swing_feel is not None:
            data["swingFeel"] = _frac(self.swing_feel)
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreRevisionPayload:
        return cls(
            tempo_map=tuple(TempoSegment.from_dict(t) for t in data.get("tempoMap", ())),
            time_signature=TimeSignature.from_dict(data["timeSignature"]),
            key_signature=KeySignature.from_dict(data["keySignature"]),
            pickup_beats=_unfrac(data.get("pickupBeats", "0/1")),
            parts=tuple(Part.from_dict(p) for p in data.get("parts", ())),
            quantization_settings=dict(data.get("quantizationSettings", {})),
            meter_changes=tuple(
                MeterChange.from_dict(m) for m in data.get("meterChanges", ())
            ),
            key_changes=tuple(
                KeyChange.from_dict(k) for k in data.get("keyChanges", ())
            ),
            swing_feel=(
                _unfrac(data["swingFeel"])
                if data.get("swingFeel") is not None
                else None
            ),
        )

    def revision_id(self) -> ScoreRevisionId:
        return derive_score_revision_id(self.to_dict())


def beat_ql_of(payload: ScoreRevisionPayload) -> Fraction:
    """QuarterLength of one canonical beat — set by the first time signature.

    With a single meter this is simply ``4/beat_unit``. With meter changes
    the *first* meter change defines the beat axis for the whole score, so
    positions stay comparable across segment boundaries.
    """
    return Fraction(4, payload.time_signature.beat_unit)


def measure_length_beats(ts: TimeSignature, beat_ql: Fraction) -> Fraction:
    """One measure of *ts* expressed in canonical beats.

    ``ts.beats_per_measure * (4/beat_unit)`` gives the measure length in
    quarterLength; dividing by ``beat_ql`` converts to canonical beats
    (for the beat-defining signature this is just ``beats_per_measure``).
    """
    if ts.beats_per_measure <= 0 or ts.beat_unit <= 0:
        raise ValueError(
            f"invalid time signature: {ts.beats_per_measure}/{ts.beat_unit}"
        )
    return Fraction(ts.beats_per_measure * 4, ts.beat_unit) / beat_ql


def primary_beat_beats(ts: TimeSignature, beat_ql: Fraction) -> Fraction:
    """Length of one primary (felt) beat of *ts* in canonical beats.

    Compound meters (``numerator % 3 == 0 and numerator > 3`` — e.g. 6/8)
    have ``numerator // 3`` dotted beats; simple meters beat on the
    denominator unit. Mirrors ``MeterSegment.beat_unit_ql`` (design 7.3).
    """
    if ts.beats_per_measure <= 0 or ts.beat_unit <= 0:
        raise ValueError(
            f"invalid time signature: {ts.beats_per_measure}/{ts.beat_unit}"
        )
    beat_count = (
        ts.beats_per_measure // 3
        if ts.beats_per_measure % 3 == 0 and ts.beats_per_measure > 3
        else ts.beats_per_measure
    )
    return measure_length_beats(ts, beat_ql) / beat_count


@dataclass(frozen=True)
class MeasureSpan:
    """One measure's span on the canonical beat axis.

    ``number`` is the MusicXML measure number (``0`` for the implicit
    anacrusis measure); ``time_signature`` is the meter active inside the
    measure; ``meter_change`` marks the first measure of a new meter — the
    notation layer emits ``<time>`` attributes there;
    ``cycle_offset_beats`` is the span's position inside its meter's measure
    cycle (``0`` except for the partial first measure of a phased segment).
    """

    number: int
    start_beat: Fraction
    end_beat: Fraction
    time_signature: TimeSignature
    meter_change: bool = False
    implicit: bool = False
    cycle_offset_beats: Fraction = Fraction(0)

    @property
    def duration_beats(self) -> Fraction:
        return self.end_beat - self.start_beat


def measure_spans(payload: ScoreRevisionPayload) -> tuple[MeasureSpan, ...]:
    """Deterministic measure layout shared by every part and every consumer.

    Layout rules (QNT-006):

    * each meter change tiles measures from its ``start_beat`` until the next
      change (or the content end for the last change), each first measure
      shortened by its ``measure_phase_beats``;
    * a meter change that falls inside a previous measure *clips* it — the
      partial measure keeps its number;
    * a ``measure_phase_beats > 0`` on the *first* change is the anacrusis:
      measure ``0`` with ``implicit`` (the existing convention); phased
      mid-piece changes keep regular numbering;
    * every segment emits at least one measure, so a meter declared beyond
      the content end still appears (as an empty measure);
    * with no ``meter_changes`` this degenerates to the historical layout:
      optional implicit pickup measure plus ``beats_per_measure`` tiling.
    """
    changes = payload.meter_changes
    if not changes:
        ts0 = payload.time_signature
        mlen0 = Fraction(ts0.beats_per_measure)
        phase0 = (
            mlen0 - payload.pickup_beats if payload.pickup_beats > 0 else Fraction(0)
        )
        changes = (MeterChange(Fraction(0), ts0, phase0),)
    beat_ql = beat_ql_of(payload)

    end = payload.pickup_beats
    for part in payload.parts:
        for n in part.notes:
            end = max(end, n.end_beat)
        for r in part.rests:
            end = max(end, r.end_beat)

    spans: list[MeasureSpan] = []
    number = 1
    for i, change in enumerate(changes):
        seg_end = changes[i + 1].start_beat if i + 1 < len(changes) else None
        mlen = measure_length_beats(change.time_signature, beat_ql)
        pos = change.start_beat
        first = True
        while first or (pos < seg_end if seg_end is not None else pos < end):
            dur = mlen - change.measure_phase_beats if first else mlen
            m_end = pos + dur
            if seg_end is not None and m_end > seg_end:
                m_end = seg_end
            if m_end <= pos:
                break  # safety: zero-length measure
            implicit = first and i == 0 and change.measure_phase_beats > 0
            span_number = 0 if implicit else number
            if not implicit:
                number += 1
            spans.append(
                MeasureSpan(
                    number=span_number,
                    start_beat=pos,
                    end_beat=m_end,
                    time_signature=change.time_signature,
                    meter_change=first and i > 0,
                    implicit=implicit,
                    cycle_offset_beats=(
                        change.measure_phase_beats if first else Fraction(0)
                    ),
                )
            )
            pos = m_end
            first = False
    return tuple(spans)


@dataclass(frozen=True)
class ScoreDocument:
    """Canonical score container. ``payload`` carries all musical content."""

    project_id: ProjectId
    payload: ScoreRevisionPayload
    title: str = ""
    source_audio_path: str | None = None
    source_audio_hash: str | None = None
    transcription_backend: str | None = None
    transcription_backend_version: str | None = None
    transcription_settings: dict[str, Any] = field(default_factory=dict)
    pitch_space: PitchSpace = PitchSpace.CONCERT

    @property
    def revision(self) -> ScoreRevisionId:
        return self.payload.revision_id()

    def to_dict(self) -> dict[str, Any]:
        if self.pitch_space is not PitchSpace.CONCERT:
            raise ValueError("canonical ScoreDocument must be concert pitch")
        return {
            "projectId": str(self.project_id),
            "revision": str(self.revision),
            "title": self.title,
            "sourceAudioPath": self.source_audio_path,
            "sourceAudioHash": self.source_audio_hash,
            "transcriptionBackend": self.transcription_backend,
            "transcriptionBackendVersion": self.transcription_backend_version,
            "transcriptionSettings": self.transcription_settings,
            "pitchSpace": self.pitch_space.value,
            "content": self.payload.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreDocument:
        space = PitchSpace(data.get("pitchSpace", "concert"))
        doc = cls(
            project_id=ProjectId(data["projectId"]),
            payload=ScoreRevisionPayload.from_dict(data["content"]),
            title=str(data.get("title", "")),
            source_audio_path=data.get("sourceAudioPath"),
            source_audio_hash=data.get("sourceAudioHash"),
            transcription_backend=data.get("transcriptionBackend"),
            transcription_backend_version=data.get("transcriptionBackendVersion"),
            transcription_settings=dict(data.get("transcriptionSettings", {})),
            pitch_space=space,
        )
        declared = data.get("revision")
        if declared is not None and declared != str(doc.revision):
            raise ValueError(
                f"score revision mismatch: declared {declared} != derived {doc.revision}"
            )
        return doc


def new_project_id() -> ProjectId:
    """Random project ID for genuinely new projects (creation-time only)."""
    from hornscribe.domain.ids import derive_project_id

    return derive_project_id({"uuid": uuid.uuid4().hex})
